func crdServerConfig(srv *platformv1alpha1.MCPServer) sdkmcp.ServerConfig {
	mc := srv.Spec.MCPServerConfig
	env := make(map[string]string, len(mc.Env)+len(mc.SecretEnv))
	for k, v := range mc.Env {
		env[k] = v
	}
	allowEnv := append([]string(nil), mc.AllowEnv...)
	allowed := make(map[string]bool, len(allowEnv))
	for _, name := range allowEnv {
		allowed[name] = true
	}
	var missing []string
	for _, se := range mc.SecretEnv {
		name := strings.TrimSpace(se.Name)
		if name == "" {
			continue
		}
		podName := mcpattach.SecretEnvPodName(srv.Name, name)
		v, ok := os.LookupEnv(podName)
		// Keep compatibility with pods created by older controllers. This path
		// cannot isolate duplicate names, but avoids breaking single-server runs
		// during a rolling controller/worker deployment.
		if !ok || v == "" {
			v, ok = os.LookupEnv(name)
		}
		if ok && v != "" {
			env[name] = v
		} else if _, inline := env[name]; !inline {
			missing = append(missing, name)
		}
		if !allowed[name] {
			allowed[name] = true
			allowEnv = append(allowEnv, name)
		}
	}
	if len(missing) > 0 {
		log.Printf("WARN: MCPServer %s: secretEnv var(s) not present in pod env: %s — the server may fail to authenticate",
			srv.Name, strings.Join(missing, ", "))
	}
	if len(env) == 0 {
		env = nil
	}
	return sdkmcp.ServerConfig{
		Type:              mc.Type,
		Command:           mc.Command,
		Args:              mc.Args,
		Env:               env,
		AllowEnv:          allowEnv,
		TrustReadOnlyHint: mc.TrustReadOnlyHint,
	}
}

func buildMCPConfig(ctx context.Context, c client.Client, namespace, workDir string, run *platformv1alpha1.AgentRun, permissionMode agentpolicy.PermissionMode) (sdkmcp.Config, map[string]struct{}, map[string]struct{}, []string) {
	cfg := sdkmcp.Config{MCPServers: make(map[string]sdkmcp.ServerConfig)}
	clusterManaged := make(map[string]struct{})
	networkAllowed := make(map[string]struct{})
	var dropped []string
	evaluator, hasPolicy, err := resolveMCPConfigPolicy(ctx, c, namespace, run)
	if err != nil {
		log.Printf("WARN: failed to resolve MCPPolicy for config filtering: %v", err)
		evaluator = mcppolicy.NewEvaluator(run, nil)
		hasPolicy = true
	}

	// Source 1: repo .mcp.json (optional).
	cfgPath := sdkmcp.ConfigPathForWorkDir(workDir)
	repoCfg, exists, err := sdkmcp.LoadConfig(cfgPath)
	if err != nil {
		log.Printf("WARN: loading repo .mcp.json: %v", err)
	} else if exists {
		for name, srv := range repoCfg.MCPServers {
			if reason := allowMCPServerConfig(name, "repo .mcp.json", evaluator, hasPolicy, permissionMode, false); reason != "" {
				dropped = append(dropped, fmt.Sprintf("%s (repo .mcp.json): %s", name, reason))
				continue
			}
			cfg.MCPServers[name] = srv
		}
		log.Printf("Loaded %d MCP server(s) from repo .mcp.json", len(repoCfg.MCPServers))
	}

	// Source 2: MCPServer CRDs (cluster-managed), including servers required
	// by attached skills.
	if run == nil {
		return cfg, clusterManaged, networkAllowed, dropped
	}
	refs := mcpattach.EffectiveMCPServerRefs(ctx, c, run)
	if len(refs) == 0 {
		return cfg, clusterManaged, networkAllowed, dropped
	}
	crdCount := 0
	for _, ref := range refs {
		srv := &platformv1alpha1.MCPServer{}
		key := types.NamespacedName{Name: ref.Name, Namespace: namespace}
		if err := c.Get(ctx, key, srv); err != nil {
			log.Printf("WARN: failed to fetch MCPServer %s: %v — skipping", key, err)
			continue
		}
		if srv.Spec.MCPServerConfig == nil || srv.Spec.MCPServerConfig.Command == "" {
			log.Printf("MCPServer %s has no server config — skipping", srv.Name)
			continue
		}
		if reason := allowMCPServerConfig(srv.Name, "MCPServer", evaluator, hasPolicy, permissionMode, true); reason != "" {
			dropped = append(dropped, fmt.Sprintf("%s (MCPServer): %s", srv.Name, reason))
			continue
		}
		cfg.MCPServers[srv.Name] = crdServerConfig(srv)
		if srv.Spec.MCPServerConfig.AllowNetwork {
			networkAllowed[srv.Name] = struct{}{}
		}
		// Host materialization is more privileged than sandbox execution and
		// requires an explicit MCPPolicy in addition to cluster provenance.
		if hasPolicy {
			clusterManaged[srv.Name] = struct{}{}
		}
		crdCount++
	}
	if crdCount > 0 {
		log.Printf("Resolved %d MCPServer CRD(s) into MCP config", crdCount)
	}
	return cfg, clusterManaged, networkAllowed, dropped
}

func TestBuildMCPConfigBridgesSecretEnvFromPodEnv(t *testing.T) {
	scheme := runtime.NewScheme()
	if err := platformv1alpha1.AddToScheme(scheme); err != nil {
		t.Fatalf("AddToScheme(platform): %v", err)
	}

	t.Setenv(mcpattach.SecretEnvPodName("grafana", "GRAFANA_SERVICE_ACCOUNT_TOKEN"), "glsa_secret")

	srv := &platformv1alpha1.MCPServer{
		ObjectMeta: metav1.ObjectMeta{Name: "grafana", Namespace: "default"},
		Spec: platformv1alpha1.MCPServerSpec{
			MCPServerConfig: &platformv1alpha1.MCPServerConfig{
				Command: "mcp-grafana",
				Env:     map[string]string{"GRAFANA_URL": "https://grafana.example"},
				SecretEnv: []platformv1alpha1.MCPServerSecretEnv{
					{Name: "GRAFANA_SERVICE_ACCOUNT_TOKEN", SecretName: "usercred-grafana", SecretKey: "token"},
					{Name: "GRAFANA_MISSING_TOKEN", SecretName: "usercred-grafana", SecretKey: "other"},
				},
			},
		},
	}
	run := &platformv1alpha1.AgentRun{
		ObjectMeta: metav1.ObjectMeta{Name: "run-secret-env", Namespace: "default"},
		Spec: platformv1alpha1.AgentRunSpec{
			MCPServerRefs: []platformv1alpha1.NamedRef{{Name: "grafana"}},
		},
	}
	c := fake.NewClientBuilder().
		WithScheme(scheme).
		WithObjects(srv).
		Build()

	cfg, _, _, _ := buildMCPConfig(context.Background(), c, "default", t.TempDir(), run, agentpolicy.PermissionModeWorkspaceWrite)

	got, ok := cfg.MCPServers["grafana"]
	if !ok {
		t.Fatal("grafana server not present in built config")
	}
	if got.Env["GRAFANA_SERVICE_ACCOUNT_TOKEN"] != "glsa_secret" {
		t.Errorf("secretEnv value not bridged into env: %v", got.Env)
	}
	if got.Env["GRAFANA_URL"] != "https://grafana.example" {
		t.Errorf("plain env dropped: %v", got.Env)
	}
	if _, present := got.Env["GRAFANA_MISSING_TOKEN"]; present {
		t.Errorf("missing pod env var must not produce an env entry: %v", got.Env)
	}
	// Both secretEnv names must be in allowEnv so the SDK credential filter
	// passes them through (the missing one may appear at the next restart).
	allow := map[string]bool{}
	for _, name := range got.AllowEnv {
		allow[name] = true
	}
	if !allow["GRAFANA_SERVICE_ACCOUNT_TOKEN"] || !allow["GRAFANA_MISSING_TOKEN"] {
		t.Errorf("secretEnv names not appended to allowEnv: %v", got.AllowEnv)
	}
	// The CRD object's own maps must not be mutated (client cache safety).
	if _, mutated := srv.Spec.MCPServerConfig.Env["GRAFANA_SERVICE_ACCOUNT_TOKEN"]; mutated {
		t.Error("CRD env map was mutated in place")
	}
	if len(srv.Spec.MCPServerConfig.AllowEnv) != 0 {
		t.Errorf("CRD allowEnv was mutated in place: %v", srv.Spec.MCPServerConfig.AllowEnv)
	}
}

func TestBuildMCPConfigPropagatesAllowEnvAndReadOnlyHint(t *testing.T) {
