func prependEnvPath(entry, existing string) string {
	if strings.TrimSpace(existing) == "" {
		return entry
	}
	return entry + string(os.PathListSeparator) + existing
}

func sandboxedInstallRunner(ctx context.Context, root string, argv []string) (string, error) {
	if err := os.MkdirAll(root, 0o700); err != nil {
		return "", fmt.Errorf("create installer root: %w", err)
	}
	executor := sdksandbox.DefaultWithConfig(sdksandbox.Config{
		Mode:          "required",
		WorkspaceRoot: root,
	})
	result, err := executor.Run(ctx, sdksandbox.Request{
		Argv:           argv,
		WorkDir:        root,
		PermissionMode: agentpolicy.PermissionModeWorkspaceWrite,
		Timeout:        uvxMaterializeTimeout,
		Env: map[string]string{
			"PIP_DISABLE_PIP_VERSION_CHECK": "1",
			"PIP_NO_INPUT":                  "1",
		},
		AllowNetwork: true,
	})
	if err != nil {
		return result.Output, err
	}
	if result.TimedOut {
		return result.Output, fmt.Errorf("installer timed out after %s", uvxMaterializeTimeout)
	}
	if result.ExitCode != 0 {
		return result.Output, fmt.Errorf("installer exited with status %d", result.ExitCode)
	}
	return result.Output, nil
}

func materializeUvxServersAt(ctx context.Context, cfg *sdkmcp.Config, clusterManaged map[string]struct{}, root string, run installRunner) (bool, []string) {
	if cfg == nil || len(cfg.MCPServers) == 0 {
		return false, nil
	}
	installed := false
	var dropped []string
	drop := func(name, reason string) {
		delete(cfg.MCPServers, name)
		dropped = append(dropped, fmt.Sprintf("%s (MCPServer): %s", name, reason))
	}
	for name, srv := range cfg.MCPServers {
		if strings.TrimSpace(srv.Command) != "uvx" {
			continue
		}
		if _, trusted := clusterManaged[name]; !trusted {
			// Repository packages execute through the normal MCP sandbox and may
			// never trigger the more privileged networked installer.
			continue
		}

		spec, exe, rest, ok := parseUvxInvocation(srv.Args)
		if !ok || !isSafeExecutableName(exe) {
			reason := fmt.Sprintf("unsupported uvx invocation %v", srv.Args)
			log.Printf("WARN: removing MCP server %q: %s", name, reason)
			drop(name, reason)
			continue
		}
		if !isImmutableUvxSpec(spec) {
			reason := fmt.Sprintf("installable uvx packages require an exact package==version pin (got %q)", spec)
			log.Printf("WARN: removing MCP server %q: %s", name, reason)
			drop(name, reason)
			continue
		}

		digest := sha256.Sum256([]byte(name + "\x00" + spec))
		toolDir := filepath.Join(root, fmt.Sprintf("%x", digest[:12]))
		if err := os.RemoveAll(toolDir); err != nil {
			reason := fmt.Sprintf("clear install directory: %v", err)
			log.Printf("WARN: removing MCP server %q: %s", name, reason)
			drop(name, reason)
			continue
		}
		if err := os.MkdirAll(toolDir, 0o700); err != nil {
			reason := fmt.Sprintf("create install directory: %v", err)
			log.Printf("WARN: removing MCP server %q: %s", name, reason)
			drop(name, reason)
			continue
		}

		ictx, cancel := context.WithTimeout(ctx, uvxMaterializeTimeout)
		output, err := run(ictx, root, []string{
			"python3", "-m", "pip", "install",
			"--disable-pip-version-check", "--no-input", "--no-cache-dir",
			"--only-binary=:all:", "--target", toolDir, spec,
		})
		cancel()
		if err != nil {
			_ = os.RemoveAll(toolDir)
			reason := fmt.Sprintf("isolated wheel install %s failed: %v", spec, err)
			log.Printf("WARN: removing MCP server %q: %s; installer output: %s",
				name, reason, tailString(output, 800))
			drop(name, reason)
			continue
		}

		binPath := filepath.Join(toolDir, "bin", exe)
		if err := validateInstalledExecutable(binPath, toolDir); err != nil {
			_ = os.RemoveAll(toolDir)
			reason := fmt.Sprintf("wheel install %s produced no safe %q command: %v", spec, exe, err)
			log.Printf("WARN: removing MCP server %q: %s", name, reason)
			drop(name, reason)
			continue
		}

		// Keep the installed wheel immutable, but launch from a private writable
		// copy inside the MCP sandbox. Some packages legitimately initialize
		// bundled binaries, caches, or generated files beside their package on
		// first run; invoking the read-only source tree directly breaks them.
		commandPath, err := writeWritableToolLauncher(toolDir, exe)
		if err != nil {
			_ = os.RemoveAll(toolDir)
			reason := fmt.Sprintf("prepare writable runtime launcher for %s: %v", spec, err)
			log.Printf("WARN: removing MCP server %q: %s", name, reason)
			drop(name, reason)
			continue
		}

		srv.Command = commandPath
		srv.Args = rest
		if srv.Env == nil {
			srv.Env = make(map[string]string)
		}
		// pip --target places importable packages beside bin/. Console-script
		// shebangs use the system interpreter, so make that target importable.
		srv.Env["PYTHONPATH"] = prependEnvPath(toolDir, srv.Env["PYTHONPATH"])
		serverPath := srv.Env["PATH"]
		if strings.TrimSpace(serverPath) == "" {
			serverPath = "${PATH}"
		}
		srv.Env["PATH"] = prependEnvPath(filepath.Join(toolDir, "bin"), serverPath)
		cfg.MCPServers[name] = srv
		installed = true
		log.Printf("MCP server %q: installed %s at run start (isolated wheel, sandbox-safe)", name, spec)
	}
	return installed, dropped
}

func TestWritableToolLauncherUsesPrivateMutableCopy(t *testing.T) {
	toolDir := t.TempDir()
	binDir := filepath.Join(toolDir, "bin")
	if err := os.MkdirAll(binDir, 0o700); err != nil {
		t.Fatal(err)
	}
	statePath := filepath.Join(toolDir, "state")
	if err := os.WriteFile(statePath, []byte("immutable"), 0o600); err != nil {
		t.Fatal(err)
	}
	serverPath := filepath.Join(binDir, "server")
	server := `#!/bin/sh
set -eu
runtime_root="$(dirname "$0")/.."
printf mutable > "$runtime_root/state"
printf '%s:%s' "$(cat "$runtime_root/state")" "$1"
`
	if err := os.WriteFile(serverPath, []byte(server), 0o700); err != nil {
		t.Fatal(err)
	}
	launcher, err := writeWritableToolLauncher(toolDir, "server")
	if err != nil {
		t.Fatalf("writeWritableToolLauncher() error = %v", err)
	}

	cmd := exec.Command(launcher, "argument")
	cmd.Env = append(os.Environ(), "TMPDIR="+t.TempDir())
	output, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("launcher error = %v, output = %s", err, output)
	}
	if got := string(output); got != "mutable:argument" {
		t.Fatalf("launcher output = %q, want %q", got, "mutable:argument")
	}
	if source, err := os.ReadFile(statePath); err != nil || string(source) != "immutable" {
		t.Fatalf("source state = %q, err = %v; immutable install was modified", source, err)
	}
}

func TestMaterializeUvxServersInstallsPinnedWheel(t *testing.T) {
	root := t.TempDir()
	cfg := &sdkmcp.Config{MCPServers: map[string]sdkmcp.ServerConfig{
		"grafana": {
			Command: "uvx",
			Args:    []string{"mcp-grafana==0.17.0", "--disable-oncall"},
			Env:     map[string]string{"GRAFANA_TOKEN": "server-secret", "PYTHONPATH": "/existing/python"},
		},
		"node": {Command: "npx", Args: []string{"-y", "some-server"}},
	}}

	var gotRoot string
	var gotArgv []string
	runner := func(_ context.Context, installRoot string, argv []string) (string, error) {
		gotRoot = installRoot
		gotArgv = append([]string(nil), argv...)
		target := argumentValue(argv, "--target")
		binDir := filepath.Join(target, "bin")
		if err := os.MkdirAll(binDir, 0o700); err != nil {
			return "", err
		}
		return "", os.WriteFile(filepath.Join(binDir, "mcp-grafana"), []byte("#!/bin/sh\n"), 0o755)
	}

	installed, dropped := materializeUvxServersAt(context.Background(), cfg, map[string]struct{}{"grafana": {}}, root, runner)
	if !installed {
		t.Fatal("expected a materialized server")
	}
	if len(dropped) != 0 {
		t.Fatalf("unexpected dropped servers: %v", dropped)
	}
	if gotRoot != root {
		t.Fatalf("runner root = %q, want %q", gotRoot, root)
	}
	joined := strings.Join(gotArgv, " ")
	for _, required := range []string{"python3 -m pip install", "--only-binary=:all:", "mcp-grafana==0.17.0"} {
		if !strings.Contains(joined, required) {
			t.Errorf("installer argv %q missing %q", joined, required)
		}
	}
	grafana := cfg.MCPServers["grafana"]
	toolDir := argumentValue(gotArgv, "--target")
	if !strings.HasPrefix(grafana.Command, filepath.Join(toolDir, ".gratefulagents")+string(os.PathSeparator)) {
		t.Fatalf("command = %q, want private runtime launcher under %q", grafana.Command, toolDir)
	}
	launcher, err := os.ReadFile(grafana.Command)
	if err != nil {
		t.Fatalf("read runtime launcher: %v", err)
	}
	for _, want := range []string{"cp -a", shellQuote(toolDir), `exec "$runtime_dir/bin/mcp-grafana" "$@"`} {
		if !strings.Contains(string(launcher), want) {
			t.Errorf("runtime launcher missing %q:\n%s", want, launcher)
		}
	}
	if strings.Join(grafana.Args, " ") != "--disable-oncall" {
		t.Fatalf("server args = %v", grafana.Args)
	}
	if grafana.Env["GRAFANA_TOKEN"] != "server-secret" {
		t.Fatal("server runtime credentials were not preserved")
	}
	if want := argumentValue(gotArgv, "--target") + string(os.PathListSeparator) + "/existing/python"; grafana.Env["PYTHONPATH"] != want {
		t.Fatalf("PYTHONPATH = %q, want %q", grafana.Env["PYTHONPATH"], want)
	}
	if want := filepath.Join(argumentValue(gotArgv, "--target"), "bin") + string(os.PathListSeparator) + "${PATH}"; grafana.Env["PATH"] != want {
		t.Fatalf("PATH = %q, want %q", grafana.Env["PATH"], want)
	}
	if cfg.MCPServers["node"].Command != "npx" {
		t.Fatal("non-uvx server was modified")
	}
}

