	}
	if err := os.WriteFile(filepath.Join(root, "ca.crt"), []byte("ca-data"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "namespace"), []byte("run-ns"), 0o600); err != nil {
		t.Fatal(err)
	}

	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("POD_NAMESPACE", "")
