func requireGit(t *testing.T) {
	t.Helper()
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git binary not available")
	}
	t.Setenv("GIT_CONFIG_GLOBAL", os.DevNull)
	t.Setenv("GIT_CONFIG_SYSTEM", os.DevNull)
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	t.Setenv("GIT_CONFIG_PARAMETERS", "")
	// Checkpoint tests create commits in throwaway clones. Git's background
	// auto-gc/maintenance can still be writing into .git when t.TempDir()
	// removes the directory, which fails the test with "directory not empty".
	t.Setenv("GIT_CONFIG_COUNT", "2")
	t.Setenv("GIT_CONFIG_KEY_0", "gc.auto")
	t.Setenv("GIT_CONFIG_VALUE_0", "0")
	t.Setenv("GIT_CONFIG_KEY_1", "maintenance.auto")
	t.Setenv("GIT_CONFIG_VALUE_1", "false")
}

func TestInitializeSubmodulesPopulatesDeclaredSubmodules(t *testing.T) {
	requireGit(t)
	// Local-path submodules use the file transport, which git refuses for
	// submodules by default (CVE-2022-39253); allow it for this process only.
	t.Setenv("GIT_CONFIG_COUNT", "1")
	t.Setenv("GIT_CONFIG_KEY_0", "protocol.file.allow")
	t.Setenv("GIT_CONFIG_VALUE_0", "always")

	libOrigin := newBareOrigin(t, "lib")
	superOrigin := newBareOrigin(t, "super")
	seed := filepath.Join(t.TempDir(), "super-seed")
	mustGit(t, "", "clone", "--quiet", superOrigin, seed)
	mustGit(t, seed, "submodule", "add", "--quiet", libOrigin, "vendor/lib")
	mustGit(t, seed, "commit", "--quiet", "-m", "add submodule")
	mustGit(t, seed, "push", "--quiet", "origin", "main")

	repoDir := filepath.Join(t.TempDir(), "repo")
	mustGit(t, "", "clone", "--quiet", "--branch", "main", superOrigin, repoDir)
	if _, err := os.Stat(filepath.Join(repoDir, "vendor", "lib", "README.md")); err == nil {
		t.Fatal("submodule worktree populated before initialization; test precondition broken")
	}

	initializeSubmodules(repoDir)

	if _, err := os.Stat(filepath.Join(repoDir, "vendor", "lib", "README.md")); err != nil {
		t.Fatalf("submodule worktree not populated: %v", err)
	}
	if status := mustGit(t, repoDir, "submodule", "status"); strings.HasPrefix(strings.TrimSpace(status), "-") {
		t.Fatalf("submodule still uninitialized: %q", status)
	}

	// Repositories without .gitmodules and unreachable submodules are no-ops
	// rather than setup failures.
	plain := filepath.Join(t.TempDir(), "plain")
	mustGit(t, "", "clone", "--quiet", libOrigin, plain)
	initializeSubmodules(plain)
	if err := os.RemoveAll(libOrigin); err != nil {
		t.Fatal(err)
	}
	broken := filepath.Join(t.TempDir(), "broken")
	mustGit(t, "", "clone", "--quiet", "--branch", "main", superOrigin, broken)
	initializeSubmodules(broken)
	if _, err := os.Stat(filepath.Join(broken, "README.md")); err != nil {
		t.Fatalf("primary checkout disturbed by failed submodule init: %v", err)
	}
}

func createEncryptedWorkspaceArchiveCommit(ctx context.Context, dir string, key, plaintext []byte, ident []string) (string, error) {
	envelope, err := encryptWorkspaceArchive(key, plaintext)
	if err != nil {
		return "", err
	}
	blobOut, err := gitOutputRaw(ctx, dir, nil, envelope, "hash-object", "-w", "--stdin")
	if err != nil {
		return "", fmt.Errorf("writing encrypted workspace archive blob: %w", err)
	}
	blob := strings.TrimSpace(string(blobOut))
	if blob == "" {
		return "", fmt.Errorf("writing encrypted workspace archive blob returned no object ID")
	}

	idx, err := os.CreateTemp("", "gratefulagents-archive-index-*")
	if err != nil {
		return "", fmt.Errorf("creating encrypted archive index: %w", err)
	}
	idxPath := idx.Name()
	_ = idx.Close()
	_ = os.Remove(idxPath)
	defer func() { _ = os.Remove(idxPath) }()
	env := []string{"GIT_INDEX_FILE=" + idxPath}
	if _, err := gitOutput(ctx, dir, env, "read-tree", "--empty"); err != nil {
		return "", fmt.Errorf("initializing encrypted archive tree: %w", err)
	}
	if _, err := gitOutput(ctx, dir, env, "update-index", "--add", "--cacheinfo", "100644", blob, encryptedWorkspaceArchivePath); err != nil {
		return "", fmt.Errorf("indexing encrypted workspace archive: %w", err)
	}
	tree, err := gitOutput(ctx, dir, env, "write-tree")
	if err != nil {
		return "", fmt.Errorf("writing encrypted workspace archive tree: %w", err)
	}
	commit, err := gitOutput(ctx, dir, ident, "commit-tree", tree, "-m", encryptedWorkspaceArchiveSubject)
	if err != nil {
		return "", fmt.Errorf("creating encrypted workspace archive commit: %w", err)
	}
	return commit, nil
}

func gitOutputRaw(ctx context.Context, dir string, extraEnv []string, stdin []byte, args ...string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = dir
	if len(extraEnv) > 0 {
		cmd.Env = append(os.Environ(), extraEnv...)
	}
	if stdin != nil {
		cmd.Stdin = bytes.NewReader(stdin)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("git %s: %w (%s)", strings.Join(args, " "), err, strings.TrimSpace(stderr.String()))
	}
	return stdout.Bytes(), nil
}

