func commandSandboxConfigEnvs(run *platformv1alpha1.AgentRun) []corev1.EnvVar {
	var envs []corev1.EnvVar
	for _, name := range sandbox.SandboxConfigEnvNames() {
		// When the run disables the command sandbox, commandSandboxModeEnvs
		// forces the allow-unsafe flag on; skip the operator-forwarded value
		// so the pod spec never carries a conflicting duplicate.
		if runDisablesCommandSandbox(run) && name == sandbox.SandboxAllowUnsafeReadOnlyLocalEnv {
			continue
		}
		if value := strings.TrimSpace(os.Getenv(name)); value != "" {
			envs = append(envs, corev1.EnvVar{Name: name, Value: value})
		}
	}
	return envs
}

func ensureWorkspaceScratchSandboxConfig(container *corev1.Container) {
	if container == nil {
		return
	}
	paths := []string{workspaceScratchPath}
	var extraEnvValue string
	for _, env := range container.Env {
		switch env.Name {
		case sandbox.SandboxExtraWritablePathsEnv:
			for _, path := range filepath.SplitList(env.Value) {
				path = strings.TrimSpace(path)
				if path != "" && path != workspaceScratchPath {
					paths = append(paths, path)
				}
			}
		case sandbox.SandboxExtraEnvEnv:
			extraEnvValue = env.Value
		}
	}
	upsertContainerEnv(container, corev1.EnvVar{
		Name:  sandbox.SandboxExtraWritablePathsEnv,
		Value: strings.Join(paths, string(os.PathListSeparator)),
	})

	// ConfigFromEnv only forwards explicitly granted variables into bwrap.
	// Normalize the legacy comma-separated form and remove stale cache entries
	// before appending the platform-owned values, making this merge idempotent.
	if !strings.Contains(extraEnvValue, "\n") {
		extraEnvValue = strings.ReplaceAll(extraEnvValue, ",", "\n")
	}
	var extraEnv []string
	for _, pair := range strings.Split(extraEnvValue, "\n") {
		pair = strings.TrimSpace(pair)
		key, _, ok := strings.Cut(pair, "=")
		if pair == "" || !ok || key == "GOPATH" || key == "GOMODCACHE" || key == "GOCACHE" {
			continue
		}
		extraEnv = append(extraEnv, pair)
	}
	extraEnv = append(extraEnv,
		"GOPATH="+workspaceScratchPath+"/go",
		"GOMODCACHE="+workspaceScratchPath+"/go/pkg/mod",
		"GOCACHE="+workspaceScratchPath+"/go-build",
	)
	upsertContainerEnv(container, corev1.EnvVar{
		Name:  sandbox.SandboxExtraEnvEnv,
		Value: strings.Join(extraEnv, "\n"),
	})
}

func ensureDockerInDocker(podSpec *corev1.PodSpec, run *platformv1alpha1.AgentRun) {
	if podSpec == nil || len(podSpec.Containers) == 0 || !runEnablesDockerInDocker(run) {
		return
	}
	podSpec.Volumes = append(podSpec.Volumes, corev1.Volume{
		Name:         dindDockerLibVolume,
		VolumeSource: corev1.VolumeSource{EmptyDir: &corev1.EmptyDirVolumeSource{}},
	})
	restartAlways := corev1.ContainerRestartPolicyAlways
	podSpec.InitContainers = append(podSpec.InitContainers, corev1.Container{
		Name:            dindContainerName,
		Image:           firstNonEmpty(os.Getenv("DIND_IMAGE"), defaultDinDImage),
		ImagePullPolicy: corev1.PullIfNotPresent,
		RestartPolicy:   &restartAlways,
		// Explicit command: keep the API on loopback only (see doc comment).
		Args: []string{"dockerd", "--host=unix:///var/run/docker.sock", "--host=" + dindDockerHost},
		// Explicitly disable the entrypoint's TLS cert generation; the API is
		// loopback-only inside the pod.
		Env: []corev1.EnvVar{{Name: "DOCKER_TLS_CERTDIR", Value: ""}},
		// dockerd needs full privileges to manage cgroups, mounts, and
		// iptables. This is inherent to Docker-in-Docker and why the option
		// is admin-gated and off by default.
		SecurityContext: &corev1.SecurityContext{Privileged: boolPtr(true)},
		VolumeMounts: []corev1.VolumeMount{
			{Name: "workspace", MountPath: "/workspace"},
			{Name: workspaceScratchVolumeName, MountPath: workspaceScratchPath},
			{Name: dindDockerLibVolume, MountPath: "/var/lib/docker"},
		},
		// Gate the worker's start on the daemon accepting connections so the
		// first docker command does not race dockerd's startup. A tcpSocket
		// probe cannot be used here: kubelet connects to the pod IP rather than
		// from inside the container, while dockerd intentionally listens only
		// on loopback to keep its unauthenticated API private to the pod.
		StartupProbe: &corev1.Probe{
			ProbeHandler: corev1.ProbeHandler{Exec: &corev1.ExecAction{Command: []string{
				"docker", "--host=" + dindDockerHost, "info", "--format", "{{json .ServerVersion}}",
			}}},
			PeriodSeconds:    2,
			FailureThreshold: 60,
		},
	})

	worker := &podSpec.Containers[0]
	upsertContainerEnv(worker, corev1.EnvVar{Name: "DOCKER_HOST", Value: dindDockerHost})
	// ConfigFromEnv only forwards explicitly granted variables into bwrap, so
	// DOCKER_HOST must also be appended to the sandbox extra-env grant.
	extraEnv := "DOCKER_HOST=" + dindDockerHost
	for i := range worker.Env {
		if worker.Env[i].Name == sandbox.SandboxExtraEnvEnv && worker.Env[i].Value != "" {
			extraEnv = worker.Env[i].Value + "\n" + extraEnv
			break
		}
	}
	upsertContainerEnv(worker, corev1.EnvVar{Name: sandbox.SandboxExtraEnvEnv, Value: extraEnv})
}

