	assertEnvValue(t, values, copilotOAuthAuthJSONEnv, openAIOAuthAuthJSONPath)
	if _, ok := envByName["COPILOT_API_KEY"]; ok {
		t.Fatalf("COPILOT_API_KEY should be omitted in oauth mode, env=%#v", envByName["COPILOT_API_KEY"])
	}
	if _, ok := envByName["OPENROUTER_API_KEY"]; !ok {
		t.Fatalf("OPENROUTER_API_KEY should still be mounted for fallback providers")
	}
	if _, ok := envByName["OPENAI_OAUTH_AUTH_JSON_PATH"]; ok {
		t.Fatalf("OPENAI_OAUTH_AUTH_JSON_PATH should be omitted for Copilot OAuth")
	}
	if !hasVolumeMount(spec.Containers[0].VolumeMounts, openAIOAuthVolumeName, openAIOAuthMountPath) {
		t.Fatalf("expected oauth volume mount %q at %q", openAIOAuthVolumeName, openAIOAuthMountPath)
	}
	if !hasSecretVolume(spec.Volumes, openAIOAuthVolumeName, "copilot-oauth") {
		t.Fatalf("expected oauth secret volume %q with secret copilot-oauth", openAIOAuthVolumeName)
	}
	if !secretVolumeProjectsKey(spec.Volumes, openAIOAuthVolumeName, "auth.json") {
		t.Fatalf("expected oauth volume %q to project auth.json", openAIOAuthVolumeName)
	}
}

const (
	// podStartupDeadlineEnv bounds how long a runner pod may stay in
	// PodPending before the run fails with a classified diagnosis instead of
	// silently consuming its maxRuntime budget (default 6h) while, for
	// example, its image cannot be pulled or no node can schedule it.
	podStartupDeadlineEnv     = "AGENTRUN_POD_STARTUP_DEADLINE_SECONDS"
	defaultPodStartupDeadline = 15 * time.Minute

	// podForceDeleteAfterEnv bounds how long a drain waits for a Terminating
	// pod past its own deletion deadline before escalating to a force delete
	// (GracePeriodSeconds=0). Pods on lost nodes otherwise stay Terminating
	// forever and wedge cancellation, wake, restart, and AgentRun deletion.
	podForceDeleteAfterEnv     = "AGENTRUN_POD_FORCE_DELETE_AFTER_SECONDS"
	defaultPodForceDeleteAfter = 90 * time.Second

	// claimDrainGiveUpAfterEnv bounds how long a drain blocks on a
	// SandboxClaim stuck Terminating behind a third-party finalizer. Past the
	// deadline the drain proceeds (the claim's controller owns the cleanup)
	// so a broken external controller cannot hang run termination forever.
	claimDrainGiveUpAfterEnv     = "AGENTRUN_CLAIM_DRAIN_GIVE_UP_AFTER_SECONDS"
	defaultClaimDrainGiveUpAfter = 10 * time.Minute

	// terminalSandboxTTLEnv is how long a terminal (Succeeded/Failed/
	// Cancelled) run keeps its sandbox compute before the controller drains
	// it. The delay preserves pod logs for post-mortem debugging; without a
	// TTL, completed runs accumulate zombie sandboxes forever.
	terminalSandboxTTLEnv     = "AGENTRUN_TERMINAL_SANDBOX_TTL_SECONDS"
	defaultTerminalSandboxTTL = 10 * time.Minute

	// overseerDetachDeadline bounds how long an overseer detach may sit in
	// the "detaching" state before its status is surfaced as degraded. The
	// underlying standing-run drain keeps escalating independently.
	overseerDetachDeadline = 5 * time.Minute
)

func durationFromSecondsEnv(name string, fallback time.Duration) time.Duration {
	raw := strings.TrimSpace(os.Getenv(name))
	if raw == "" {
		return fallback
	}
	seconds, err := strconv.Atoi(raw)
	if err != nil || seconds <= 0 {
		return fallback
	}
	return time.Duration(seconds) * time.Second
}

func podStartupDeadline() time.Duration {
	return durationFromSecondsEnv(podStartupDeadlineEnv, defaultPodStartupDeadline)
}

func podForceDeleteAfter() time.Duration {
	return durationFromSecondsEnv(podForceDeleteAfterEnv, defaultPodForceDeleteAfter)
}

func claimDrainGiveUpAfter() time.Duration {
	return durationFromSecondsEnv(claimDrainGiveUpAfterEnv, defaultClaimDrainGiveUpAfter)
}

func terminalSandboxTTL() time.Duration {
	return durationFromSecondsEnv(terminalSandboxTTLEnv, defaultTerminalSandboxTTL)
}

func TestDurationFromSecondsEnvOverride(t *testing.T) {
	t.Setenv(podStartupDeadlineEnv, "60")
	if got := podStartupDeadline(); got != time.Minute {
		t.Fatalf("podStartupDeadline() = %v, want 1m", got)
	}
	t.Setenv(podStartupDeadlineEnv, "garbage")
	if got := podStartupDeadline(); got != defaultPodStartupDeadline {
		t.Fatalf("podStartupDeadline() with invalid env = %v, want default %v", got, defaultPodStartupDeadline)
	}
}

func TestMonitorPodPendingFailsAtStartupDeadline(t *testing.T) {
	t.Setenv(podStartupDeadlineEnv, "60")
	scheme := terminationTestScheme(t)
	run := runWithPodSandbox("run-stuck", platformv1alpha1.AgentRunPhaseProvisioning, "run-stuck-pod")
	now := metav1.Now()
	run.Status.StartedAt = &now
	pod := &corev1.Pod{
		ObjectMeta: metav1.ObjectMeta{
			Name: "run-stuck-pod", Namespace: "default",
			CreationTimestamp: metav1.Time{Time: time.Now().Add(-2 * time.Minute)},
		},
		Status: corev1.PodStatus{
			Phase: corev1.PodPending,
			Conditions: []corev1.PodCondition{{
				Type: corev1.PodScheduled, Status: corev1.ConditionFalse,
				Reason: "Unschedulable", Message: "0/3 nodes are available",
			}},
		},
	}
	c := fake.NewClientBuilder().WithScheme(scheme).WithStatusSubresource(&platformv1alpha1.AgentRun{}).WithObjects(run, pod).Build()
	r := &AgentRunReconciler{Client: c}
	if _, err := r.monitorPodName(context.Background(), run, "run-stuck-pod", time.Second); err != nil {
		t.Fatalf("monitorPodName() error = %v", err)
	}
	updated := &platformv1alpha1.AgentRun{}
	if err := c.Get(context.Background(), client.ObjectKeyFromObject(run), updated); err != nil {
		t.Fatal(err)
	}
	if updated.Status.Phase != platformv1alpha1.AgentRunPhaseFailed {
		t.Fatalf("phase = %q, want Failed after startup deadline", updated.Status.Phase)
	}
	if !strings.Contains(updated.Status.LastError, "unschedulable") {
		t.Fatalf("LastError = %q, want unschedulable diagnosis", updated.Status.LastError)
	}
}

func TestReconcileTerminalRunDrainsSandboxAfterTTL(t *testing.T) {
	t.Setenv(terminalSandboxTTLEnv, "60")
	scheme := terminationTestScheme(t)
	run := runWithPodSandbox("run-done", platformv1alpha1.AgentRunPhaseSucceeded, "run-done-pod")
	completed := metav1.Time{Time: time.Now().Add(-5 * time.Minute)}
	run.Status.CompletedAt = &completed
	pod := &corev1.Pod{ObjectMeta: metav1.ObjectMeta{
		Name: "run-done-pod", Namespace: "default",
		Labels: map[string]string{"platform.gratefulagents.dev/owner-run-uid": string(run.UID)},
	}}
	c := fake.NewClientBuilder().WithScheme(scheme).WithStatusSubresource(&platformv1alpha1.AgentRun{}).WithObjects(run, pod).Build()
	r := &AgentRunReconciler{Client: c}

	// First pass: the TTL has elapsed, so the drain deletes the pod.
	result, err := r.Reconcile(context.Background(), ctrl.Request{NamespacedName: client.ObjectKeyFromObject(run)})
	if err != nil {
		t.Fatalf("Reconcile() error = %v", err)
	}
	if result.RequeueAfter == 0 {
		t.Fatalf("result = %#v, want requeue while draining", result)
	}
	if err := c.Get(context.Background(), client.ObjectKey{Namespace: "default", Name: "run-done-pod"}, &corev1.Pod{}); err == nil {
		t.Fatal("zombie pod still exists after TTL drain pass")
	}

	// Second pass: fully drained, sandbox status cleared, no more requeue.
	result, err = r.Reconcile(context.Background(), ctrl.Request{NamespacedName: client.ObjectKeyFromObject(run)})
	if err != nil {
		t.Fatalf("Reconcile() second pass error = %v", err)
	}
	if result.RequeueAfter != 0 {
		t.Fatalf("result = %#v, want steady state after drain", result)
	}
	updated := &platformv1alpha1.AgentRun{}
	if err := c.Get(context.Background(), client.ObjectKeyFromObject(run), updated); err != nil {
		t.Fatal(err)
	}
	if updated.Status.Sandbox != nil {
		t.Fatal("status.Sandbox not cleared after terminal drain")
	}
	if updated.Status.Phase != platformv1alpha1.AgentRunPhaseSucceeded {
		t.Fatalf("phase = %q, want terminal phase preserved", updated.Status.Phase)
	}
}

func ensureRunSandboxTemplate(ctx context.Context, c client.Client, run *platformv1alpha1.AgentRun, runtimeProfile *platformv1alpha1.RuntimeProfile, saName, workspacePVCName string) (string, error) {
	var baseTemplate *extensionsv1alpha1.SandboxTemplate
	if explicit := explicitSandboxTemplateRef(runtimeProfile); explicit != "" {
		baseTemplate = &extensionsv1alpha1.SandboxTemplate{}
		if err := c.Get(ctx, client.ObjectKey{Name: explicit, Namespace: run.Namespace}, baseTemplate); err != nil {
			if apierrors.IsNotFound(err) {
				return "", fmt.Errorf("sandbox template %s/%s not found", run.Namespace, explicit)
			}
			return "", fmt.Errorf("getting sandbox template %s/%s: %w", run.Namespace, explicit, err)
		}
	}

	name := managedSandboxTemplateName(run)
	sshTunnel, err := resolveSSHTunnel(ctx, c, run)
	if err != nil {
		return "", err
	}
	template := &extensionsv1alpha1.SandboxTemplate{
		ObjectMeta: metav1.ObjectMeta{
			Name:            name,
			Namespace:       run.Namespace,
			Labels:          sandboxTemplateLabels(run),
			OwnerReferences: []metav1.OwnerReference{runOwnerRef(run)},
		},
		Spec: buildManagedSandboxTemplateSpec(run, runtimeProfile, saName, baseTemplate, workspacePVCName,
			resolveMCPServerSecretEnvs(ctx, c, run), sshTunnel),
	}
	if err := c.Create(ctx, template); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return "", fmt.Errorf("creating sandbox template: %w", err)
		}
		existing := &extensionsv1alpha1.SandboxTemplate{}
		if getErr := c.Get(ctx, client.ObjectKey{Name: name, Namespace: run.Namespace}, existing); getErr != nil {
			return "", fmt.Errorf("getting existing sandbox template: %w", getErr)
		}
		if !sandboxTemplateOwnedByRun(existing, run) {
			return "", fmt.Errorf("sandbox template %s/%s already belongs to another AgentRun", run.Namespace, name)
		}
	}
	return name, nil
}

func buildManagedSandboxTemplateSpec(
	run *platformv1alpha1.AgentRun,
	runtimeProfile *platformv1alpha1.RuntimeProfile,
	saName string,
	baseTemplate *extensionsv1alpha1.SandboxTemplate,
	workspacePVCName string,
	secretEnvs []corev1.EnvVar,
	sshTunnel *platformv1alpha1.SSHTunnel,
) extensionsv1alpha1.SandboxTemplateSpec {
	envs := runExecutionEnvVars(run)
	envs = append(envs, secretEnvs...)
	podSpec := buildCommonPodSpec(run, saName, []string{"/opt/gratefulagents/bin/agent", "run"}, envs, nil, nil)
	ensureSSHTunnelSidecar(&podSpec, sshTunnel)
	podSpec.AutomountServiceAccountToken = boolPtr(true)
	applyRuntimeProfileSandboxOverrides(&podSpec, runtimeProfile, workspacePVCName)

	spec := extensionsv1alpha1.SandboxTemplateSpec{}
	if baseTemplate != nil {
		spec = *baseTemplate.Spec.DeepCopy()
	}
	spec.PodTemplate = sandboxv1alpha1.PodTemplate{
		Spec: podSpec,
		ObjectMeta: sandboxv1alpha1.PodMetadata{
			Labels: map[string]string{
				"platform.gratefulagents.dev/owner-run":     run.Name,
				"platform.gratefulagents.dev/owner-run-uid": string(run.UID),
			},
			Annotations: map[string]string{},
		},
	}
	if baseTemplate != nil {
		spec.PodTemplate.ObjectMeta = *baseTemplate.Spec.PodTemplate.ObjectMeta.DeepCopy()
		if spec.PodTemplate.ObjectMeta.Labels == nil {
			spec.PodTemplate.ObjectMeta.Labels = map[string]string{}
		}
		spec.PodTemplate.ObjectMeta.Labels["platform.gratefulagents.dev/owner-run"] = run.Name
		spec.PodTemplate.ObjectMeta.Labels["platform.gratefulagents.dev/owner-run-uid"] = string(run.UID)
	}
	if spec.NetworkPolicyManagement == "" {
		spec.NetworkPolicyManagement = extensionsv1alpha1.NetworkPolicyManagementManaged
	}
	if networkPolicy := buildRuntimeProfileNetworkPolicy(runtimeProfile); networkPolicy != nil {
		spec.NetworkPolicy = networkPolicy
	}
	return spec
}

func applyRuntimeProfileCommandSandboxConfig(podSpec *corev1.PodSpec, runtimeProfile *platformv1alpha1.RuntimeProfile) {
	if podSpec == nil || len(podSpec.Containers) == 0 {
		return
	}
	upsertContainerEnv(&podSpec.Containers[0], runtimeProfileCommandSandboxConfigEnvs(runtimeProfile)...)
}

func upsertContainerEnv(container *corev1.Container, envs ...corev1.EnvVar) {
	if container == nil {
		return
	}
	for _, next := range envs {
		if strings.TrimSpace(next.Name) == "" {
			continue
		}
		replaced := false
		for i := range container.Env {
			if container.Env[i].Name == next.Name {
				container.Env[i] = next
				replaced = true
				break
			}
		}
		if !replaced {
			container.Env = append(container.Env, next)
		}
	}
}

func runExecutionEnvVars(run *platformv1alpha1.AgentRun) []corev1.EnvVar {
	envs := []corev1.EnvVar{
		{Name: "PLANTASK_NAME", Value: run.Name},
		{Name: "PLANTASK_UID", Value: string(run.UID)},
	}
	if run.Spec.Debug {
		envs = append(envs, corev1.EnvVar{Name: "AI_DEBUG", Value: "1"})
	}
	candidate := run.Labels[metaHarnessLabel]
	if candidate != "" || strings.EqualFold(os.Getenv("ENABLE_METAHARNESS"), "true") {
		envs = append(envs, corev1.EnvVar{Name: "ENABLE_METAHARNESS", Value: "true"})
		if candidate != "" {
			envs = append(envs, corev1.EnvVar{Name: "METAHARNESS_CANDIDATE", Value: candidate})
		}
	}
	return envs
}

func (r *SecurityToolRunReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	log := logf.FromContext(ctx)

	run := &platformv1alpha1.SecurityToolRun{}
	if err := r.Get(ctx, req.NamespacedName, run); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}
	if !run.DeletionTimestamp.IsZero() {
		return ctrl.Result{}, nil
	}
	if isTerminalSecurityToolRun(run) {
		return r.reconcileStagedCleanup(ctx, run)
	}

	registry := r.Registry
	if registry == nil {
		built, err := securitytoolrun.DefaultRegistry()
		if err != nil {
			return ctrl.Result{}, fmt.Errorf("building security tool registry: %w", err)
		}
		registry = built
	}

	request, err := securitytoolrun.RunConfigFor(run.Spec)
	if err != nil {
		return ctrl.Result{}, r.failRun(ctx, run, "InvalidRequest", err.Error(), "error")
	}
	tool, err := securitytoolrun.Validate(registry, request)
	if err != nil {
		return ctrl.Result{}, r.failRun(ctx, run, "InvalidRequest", err.Error(), "error")
	}
	if staged := strings.TrimSpace(run.Spec.Target.StagedObjectKey); staged != "" {
		if expected := securitytoolrun.TargetObjectKey(run.Namespace, run.Name); staged != expected {
			return ctrl.Result{}, r.failRun(ctx, run, "InvalidRequest",
				fmt.Sprintf("staged target must be %s, got %s", expected, staged), "error")
		}
	}
	if securitytoolrun.NeedsNetworkAuthorization(tool, request) {
		authorized, err := r.authorizedNetworkTargets(ctx, run)
		if err != nil {
			var refusal *securityToolRunRefusal
			if errors.As(err, &refusal) {
				return ctrl.Result{}, r.failRun(ctx, run, refusal.reason, refusal.message, "error")
			}
			return ctrl.Result{}, err
		}
		if err := securitytoolrun.AuthorizeNetworkTargets(authorized, request); err != nil {
			return ctrl.Result{}, r.failRun(ctx, run, "NetworkTargetNotAuthorized", err.Error(), "error")
		}
	}
	image, err := resolveSecurityToolsImage()
	if err != nil {
		return ctrl.Result{}, r.failRun(ctx, run, "InvalidImage", err.Error(), "error")
	}

	job := &batchv1.Job{}
	jobKey := client.ObjectKey{Namespace: run.Namespace, Name: securityToolRunJobName(run.Name)}
	switch err := r.Get(ctx, jobKey, job); {
	case apierrors.IsNotFound(err):
		// A Job this run already started and that no longer exists took its
		// verdict with it. Re-creating it would re-execute a scan the
		// requester already believes is running. A freshly created Job may
		// simply not be in the cache yet, so wait it out first.
		if run.Status.JobName != "" || run.Status.Phase == platformv1alpha1.SecurityToolRunPhaseRunning {
			if started := run.Status.StartedAt; started != nil && time.Since(started.Time) < securityToolsJobVisibilityGrace {
				return ctrl.Result{RequeueAfter: securityToolsRequeue}, nil
			}
			return ctrl.Result{}, r.failRun(ctx, run, "JobDisappeared",
				fmt.Sprintf("execution Job %s no longer exists; a scan is never re-executed", jobKey.Name), "error")
		}
		if err := r.startJob(ctx, run, request.RunConfig, tool, image); err != nil {
			var refusal *securityToolRunRefusal
			if errors.As(err, &refusal) {
				return ctrl.Result{}, r.failRun(ctx, run, refusal.reason, refusal.message, "error")
			}
			return ctrl.Result{}, err
		}
		log.Info("SecurityToolRun job created", "name", run.Name, "job", jobKey.Name, "tool", tool.Name)
		return ctrl.Result{RequeueAfter: securityToolsRequeue}, r.markRunning(ctx, run, jobKey.Name, image)
	case err != nil:
		return ctrl.Result{}, fmt.Errorf("getting Job %s: %w", jobKey.Name, err)
	}
	if !metav1.IsControlledBy(job, run) {
		return ctrl.Result{}, r.failRun(ctx, run, "JobNameConflict",
			fmt.Sprintf("Job %s is not controlled by this SecurityToolRun", jobKey.Name), "error")
	}

	complete, failed, failureReason := securityToolJobState(job)
	switch {
	case complete:
		return r.completeRun(ctx, run, job)
	case failed:
		resultStatus := "error"
		if failureReason == "DeadlineExceeded" {
			resultStatus = "timeout"
		}
		message := fmt.Sprintf("execution Job %s failed", job.Name)
		if failureReason != "" {
			message = fmt.Sprintf("execution Job %s failed: %s", job.Name, failureReason)
		}
		return ctrl.Result{}, r.failRun(ctx, run, "JobFailed", message, resultStatus)
	default:
		return ctrl.Result{RequeueAfter: securityToolsRequeue}, r.markRunning(ctx, run, job.Name, image)
	}
}

func resolveSecurityToolsImage() (string, error) {
	image := strings.TrimSpace(os.Getenv(securityToolsImageEnv))
	if image == "" {
		return "", fmt.Errorf("%s is not configured on the controller manager", securityToolsImageEnv)
	}
	if strings.Contains(image, "@sha256:") {
		return image, nil
	}
	if strings.EqualFold(strings.TrimSpace(os.Getenv(securityToolsAllowUnpinnedEnv)), "true") {
		return image, nil
	}
	return "", fmt.Errorf("%s %q must be digest pinned (image@sha256:...); set %s=true to override",
		securityToolsImageEnv, image, securityToolsAllowUnpinnedEnv)
}

func securityToolsJobTTLSeconds() int32 {
	raw := strings.TrimSpace(os.Getenv(securityToolsJobTTLEnv))
	if raw == "" {
		return securityToolsDefaultTTLSeconds
	}
	seconds, err := strconv.Atoi(raw)
	// A short TTL deletes the Job before its Complete condition can be
	// observed, which reads as a vanished Job and loses the verdict.
	if err != nil || seconds < securityToolsMinTTLSeconds || seconds > math.MaxInt32 {
		return securityToolsDefaultTTLSeconds
	}
	return int32(seconds)
}

func (r *SecurityToolRunReconciler) startJob(ctx context.Context, run *platformv1alpha1.SecurityToolRun, config securitytoolpacks.RunConfig, tool securitytoolpacks.Tool, image string) error {
	if err := ensureWorkerInfraSecret(ctx, r.Client, run.Namespace); err != nil {
		return fmt.Errorf("syncing worker infra secret: %w", err)
	}
	encoded, err := json.Marshal(config)
	if err != nil {
		return fmt.Errorf("encoding run config: %w", err)
	}
	owner := securityToolRunOwnerRef(run)
	configMap := &corev1.ConfigMap{
		ObjectMeta: metav1.ObjectMeta{
			Name:            securityToolRunConfigMapName(run.Name),
			Namespace:       run.Namespace,
			OwnerReferences: []metav1.OwnerReference{owner},
		},
		// Agent service accounts may create ConfigMaps in their namespace, so
		// the execution inputs are pinned: an immutable ConfigMap cannot be
		// edited after the Job mounts it, and a pre-existing one is only
		// accepted when this run owns it and its bytes are identical.
		Immutable: new(true),
		Data:      map[string]string{securitytoolrun.ConfigFileName: string(encoded)},
	}
	if err := r.Create(ctx, configMap); err != nil {
		if !apierrors.IsAlreadyExists(err) {
			return fmt.Errorf("creating ConfigMap %s: %w", configMap.Name, err)
		}
		if err := r.verifyExecutionConfigMap(ctx, run, configMap); err != nil {
			return err
		}
	}
	job := securityToolRunJob(run, tool, image, owner)
	if err := r.Create(ctx, job); err != nil && !apierrors.IsAlreadyExists(err) {
		return fmt.Errorf("creating Job %s: %w", job.Name, err)
	}
	return nil
}

const (
	securityToolsImageEnv          = "SECURITY_TOOLS_IMAGE"
	securityToolsAllowUnpinnedEnv  = "SECURITY_TOOLS_ALLOW_UNPINNED_IMAGE"
	securityToolsJobTTLEnv         = "SECURITY_TOOLS_JOB_TTL_SECONDS"
	securityToolsDefaultTTLSeconds = 600
	// securityToolsMinTTLSeconds keeps a finished Job around long enough for
	// the controller to observe its terminal condition and read the manifest.
	securityToolsMinTTLSeconds = 60
	// securityToolsDeadlineSlack covers staging, image pull, and result upload
	// on top of the registry timeout budget for the scan itself.
	securityToolsDeadlineSlack = 120 * time.Second
	securityToolsRequeue       = 15 * time.Second
	// securityToolsJobVisibilityGrace absorbs informer lag: a Job created
	// moments ago may not be in the cache yet, and that is not a vanished Job.
	securityToolsJobVisibilityGrace = time.Minute
	// securityToolsRunAsID is the nonroot uid/gid baked into the security
	// tools image.
	securityToolsRunAsID int64 = 65532
	// The status payload the Job supplies is clamped to the CRD limits so an
	// oversized manifest cannot make every status patch fail.
	// The EVM packs resolve fork endpoints and upstream mirrors from operator
	// process environment inside the Job, so the manager forwards exactly
	// these names and nothing else.
	securityToolEVMForkEndpointsEnv        = "GA_SECURITY_EVM_FORK_ENDPOINTS"
	securityToolEVMForkEndpointEnvPrefix   = "GA_SECURITY_EVM_FORK_ENDPOINT_"
	securityToolEVMUpstreamMirrorEnvPrefix = "GA_SECURITY_EVM_UPSTREAM_MIRROR_"

	// Status-subresource field bounds. They mirror the CRD's own MaxLength
	// markers: a value the API server rejects would discard the whole run.
	securityToolMaxStatusShortField  = 512
	securityToolMaxStatusDigestField = 256
	securityToolMaxStatusCoverage    = 2048
	securityToolMaxStatusSeeds       = 32

	securityToolMaxStatusErrors     = 32
	securityToolMaxStatusErrorBytes = 1 << 10
	securityToolMaxStatusArtifacts  = 64

	// securityToolStagedCleanupCondition durably records whether the staged
	// customer archive has been dropped, so a transient object-store failure
	// is retried by later reconciles instead of retaining the archive forever.
	securityToolStagedCleanupCondition = "StagedTargetCleanup"
	// securityToolStagedCleanupAbandonedReason marks the retry window closed:
	// the archive may still exist and the run says so.
	securityToolStagedCleanupAbandonedReason = "Abandoned"
	securityToolsStagedCleanupBackoff        = 15 * time.Second
	securityToolsStagedCleanupMaxBackoff     = 5 * time.Minute
	securityToolsStagedCleanupDeadline       = 30 * time.Minute
)

func securityToolRunJob(run *platformv1alpha1.SecurityToolRun, tool securitytoolpacks.Tool, image string, owner metav1.OwnerReference) *batchv1.Job {
	workLimit := max(tool.Budgets.MaxOutputSize*4, 1<<30)
	const tmpLimit int64 = 256 << 20
	env := []corev1.EnvVar{
		{Name: securitytoolrun.EnvConfig, Value: securitytoolrun.ConfigPath},
		{Name: securitytoolrun.EnvWorkdir, Value: securitytoolrun.WorkDir},
		{Name: securitytoolrun.EnvTargetKey, Value: strings.TrimSpace(run.Spec.Target.StagedObjectKey)},
		{Name: securitytoolrun.EnvTargetDigest, Value: strings.TrimSpace(run.Spec.Target.Digest)},
		{Name: securitytoolrun.EnvOutputPrefix, Value: securitytoolrun.OutputPrefix(run.Namespace, run.Name)},
		// The container rootfs is read-only: everything the run writes,
		// including tool caches under HOME, belongs in the work emptyDir.
		{Name: "HOME", Value: securitytoolrun.WorkDir},
	}
	for _, name := range []string{"S3_BUCKET", "S3_ENDPOINT", "S3_REGION"} {
		if value := strings.TrimSpace(os.Getenv(name)); value != "" {
			env = append(env, corev1.EnvVar{Name: name, Value: value})
		}
	}
	env = append(env,
		workerInfraSecretEnv("AWS_ACCESS_KEY_ID", workerInfraKeyAWSAccessKeyID),
		workerInfraSecretEnv("AWS_SECRET_ACCESS_KEY", workerInfraKeyAWSSecretAccessKey),
	)
	env = append(env, securityToolOperatorEVMEnv()...)

	backoffLimit := int32(0)
	ttl := securityToolsJobTTLSeconds()
	deadline := int64((tool.Budgets.Timeout + securityToolsDeadlineSlack).Seconds())
	var nodeSelector map[string]string
	if tool.Name == "medusa" {
		nodeSelector = map[string]string{corev1.LabelArchStable: "amd64"}
	}
	return &batchv1.Job{
		ObjectMeta: metav1.ObjectMeta{
			Name:            securityToolRunJobName(run.Name),
			Namespace:       run.Namespace,
			OwnerReferences: []metav1.OwnerReference{owner},
			Labels: map[string]string{
				"app.kubernetes.io/name":                      "gratefulagents-security-tool",
				"platform.gratefulagents.dev/securitytoolrun": truncateSecurityToolRunName(run.Name, 63),
			},
		},
		Spec: batchv1.JobSpec{
			BackoffLimit:            &backoffLimit,
			TTLSecondsAfterFinished: &ttl,
			ActiveDeadlineSeconds:   &deadline,
			Template: corev1.PodTemplateSpec{
				Spec: corev1.PodSpec{
					NodeSelector:                 nodeSelector,
					RestartPolicy:                corev1.RestartPolicyNever,
					AutomountServiceAccountToken: new(false),
					Containers: []corev1.Container{{
						Name:       "security-tool",
						Image:      image,
						Command:    []string{"ga-security", "job"},
						WorkingDir: securitytoolrun.WorkDir,
						Env:        env,
						Resources: corev1.ResourceRequirements{
							Requests: corev1.ResourceList{
								corev1.ResourceCPU:    *resource.NewMilliQuantity(int64(tool.Budgets.CPU), resource.DecimalSI),
								corev1.ResourceMemory: *resource.NewQuantity(tool.Budgets.Memory, resource.BinarySI),
							},
							Limits: corev1.ResourceList{
								corev1.ResourceCPU:              *resource.NewMilliQuantity(int64(tool.Budgets.CPU), resource.DecimalSI),
								corev1.ResourceMemory:           *resource.NewQuantity(tool.Budgets.Memory, resource.BinarySI),
								corev1.ResourceEphemeralStorage: *resource.NewQuantity(workLimit+2*tmpLimit, resource.BinarySI),
							},
						},
						SecurityContext: &corev1.SecurityContext{
							RunAsUser:                new(securityToolsRunAsID),
							RunAsGroup:               new(securityToolsRunAsID),
							RunAsNonRoot:             new(true),
							AllowPrivilegeEscalation: new(false),
							ReadOnlyRootFilesystem:   new(true),
							SeccompProfile:           &corev1.SeccompProfile{Type: corev1.SeccompProfileTypeRuntimeDefault},
							Capabilities:             &corev1.Capabilities{Drop: []corev1.Capability{"ALL"}},
						},
						VolumeMounts: []corev1.VolumeMount{
							{Name: "work", MountPath: securitytoolrun.WorkDir},
							{Name: "tmp", MountPath: "/tmp"},
							{Name: "config", MountPath: securitytoolrun.ConfigMountPath, ReadOnly: true},
						},
					}},
					Volumes: []corev1.Volume{
						{Name: "work", VolumeSource: corev1.VolumeSource{EmptyDir: &corev1.EmptyDirVolumeSource{
							SizeLimit: resource.NewQuantity(workLimit, resource.BinarySI),
						}}},
						{Name: "tmp", VolumeSource: corev1.VolumeSource{EmptyDir: &corev1.EmptyDirVolumeSource{
							SizeLimit: resource.NewQuantity(tmpLimit, resource.BinarySI),
						}}},
						{Name: "config", VolumeSource: corev1.VolumeSource{ConfigMap: &corev1.ConfigMapVolumeSource{
							LocalObjectReference: corev1.LocalObjectReference{Name: securityToolRunConfigMapName(run.Name)},
						}}},
					},
				},
			},
		},
	}
}

func (r *SecurityToolRunReconciler) completeRun(ctx context.Context, run *platformv1alpha1.SecurityToolRun, job *batchv1.Job) (ctrl.Result, error) {
	blobs, err := r.blobStore()
	if err != nil {
		return ctrl.Result{}, fmt.Errorf("building object store client: %w", err)
	}
	key := securitytoolrun.ManifestObjectKey(run.Namespace, run.Name)
	raw, err := blobs.Get(ctx, key)
	if err != nil {
		if !errors.Is(err, store.ErrContentBlobNotFound) && !manifestReadWindowClosed(job, time.Now()) {
			logf.FromContext(ctx).Info("SecurityToolRun manifest is temporarily unreadable; retrying",
				"name", run.Name, "key", key, "error", err.Error())
			return ctrl.Result{RequeueAfter: securityToolsRequeue}, nil
		}
		return ctrl.Result{}, r.failRun(ctx, run, "ManifestUnreadable", fmt.Sprintf("reading %s: %v", key, err), "error")
	}
	var manifest securitytoolrun.Manifest
	if err := json.Unmarshal(raw, &manifest); err != nil {
		return ctrl.Result{}, r.failRun(ctx, run, "ManifestInvalid", fmt.Sprintf("parsing %s: %v", key, err), "error")
	}
	if err := manifest.ValidateFor(securitytoolrun.OutputPrefix(run.Namespace, run.Name)); err != nil {
		return ctrl.Result{}, r.failRun(ctx, run, "ManifestInvalid", fmt.Sprintf("validating %s: %v", key, err), "error")
	}
	if manifest.Tool != run.Spec.Tool {
		return ctrl.Result{}, r.failRun(ctx, run, "ManifestInvalid",
			fmt.Sprintf("manifest reports tool %q, expected %q", manifest.Tool, run.Spec.Tool), "error")
	}

	result := &platformv1alpha1.SecurityToolRunResult{
		// A Job that still reports the retired "pass" verdict is recorded as
		// what it actually established: nothing was found under this run's
		// bounds. It never meant the target was safe.
		Status:               normalizeSecurityToolVerdict(manifest.Status),
		FindingCount:         clampInt32(manifest.FindingCount),
		ResultObjectKey:      manifest.ResultObjectKey,
		ResultDigest:         manifest.ResultDigest,
		Errors:               clampSecurityToolErrors(manifest.Errors),
		ReproducibilityClass: manifest.ReproducibilityClass,
	}
	if scope := manifest.BoundedScope; scope != nil {
		// The status subresource has hard field limits: an oversized coverage
		// summary would make the API server reject the update and lose an
		// otherwise successful run.
		seeds := scope.Seeds
		if len(seeds) > securityToolMaxStatusSeeds {
			seeds = seeds[:securityToolMaxStatusSeeds]
		}
		result.BoundedScope = &platformv1alpha1.SecurityToolRunBoundedScope{
			Harness:     clampStatusField(scope.Harness, securityToolMaxStatusShortField),
			Corpus:      clampStatusField(scope.Corpus, securityToolMaxStatusShortField),
			Seeds:       seeds,
			Bounds:      clampStatusField(scope.Bounds, securityToolMaxStatusShortField),
			Environment: clampStatusField(scope.Environment, securityToolMaxStatusShortField),
			Coverage:    clampStatusField(scope.Coverage, securityToolMaxStatusCoverage),
		}
	}
	if health := manifest.HarnessHealth; health != nil {
		result.HarnessHealth = &platformv1alpha1.SecurityToolRunHarnessHealth{
			EntryPointReached:     health.EntryPointReached,
			TargetCodeExecuted:    health.TargetCodeExecuted,
			NegativeControlRan:    health.NegativeControlRan,
			NegativeControlPassed: health.NegativeControlPassed,
			OracleCanFail:         health.OracleCanFail,
			MutationsKilled:       clampInt32(health.MutationsKilled),
			MutationsTotal:        clampInt32(health.MutationsTotal),
			Notes:                 clampStatusField(health.Notes, securityToolMaxStatusShortField),
		}
	}
	if trials := manifest.Trials; trials != nil {
		result.Trials = &platformv1alpha1.SecurityToolRunTrials{
			Attempts:            clampInt32(trials.Attempts),
			Successes:           clampInt32(trials.Successes),
			StoppingRule:        clampStatusField(trials.StoppingRule, securityToolMaxStatusShortField),
			EquivalenceCriteria: clampStatusField(trials.EquivalenceCriteria, securityToolMaxStatusShortField),
			TraceDigest:         clampStatusField(trials.TraceDigest, securityToolMaxStatusDigestField),
			Topology:            clampStatusField(trials.Topology, securityToolMaxStatusShortField),
			ForkState:           clampStatusField(trials.ForkState, securityToolMaxStatusShortField),
		}
	}
	for _, artifact := range manifest.Artifacts {
		if len(result.Artifacts) == securityToolMaxStatusArtifacts {
			break
		}
		result.Artifacts = append(result.Artifacts, platformv1alpha1.SecurityToolRunArtifact{
			Name:      artifact.Name,
			MediaType: artifact.MediaType,
			Digest:    artifact.Digest,
			Size:      artifact.Size,
			ObjectKey: artifact.ObjectKey,
		})
	}
	message := fmt.Sprintf("tool %s reported %s with %d findings", manifest.Tool, manifest.Status, manifest.FindingCount)
	if err := r.patchStatus(ctx, run, func(fresh *platformv1alpha1.SecurityToolRun) {
		fresh.Status.Phase = platformv1alpha1.SecurityToolRunPhaseSucceeded
		fresh.Status.Message = message
		fresh.Status.Result = result
		fresh.Status.CompletedAt = new(metav1.Now())
		setCondition(&fresh.Status.Conditions, "Ready", metav1.ConditionFalse, "Completed", message)
		setCondition(&fresh.Status.Conditions, "Completed", metav1.ConditionTrue, "JobComplete", message)
	}); err != nil {
		return ctrl.Result{}, err
	}
	settled, err := r.deleteStagedTarget(ctx, run)
	if err != nil {
		return ctrl.Result{}, err
	}
	if !settled {
		return ctrl.Result{RequeueAfter: securityToolsStagedCleanupBackoff}, nil
	}
	return ctrl.Result{}, nil
}

func manifestReadWindowClosed(job *batchv1.Job, now time.Time) bool {
	completed := metav1.Time{}
	if job.Status.CompletionTime != nil {
		completed = *job.Status.CompletionTime
	} else {
		for _, condition := range job.Status.Conditions {
			if condition.Type == batchv1.JobComplete && condition.Status == corev1.ConditionTrue {
				completed = condition.LastTransitionTime
			}
		}
	}
	if completed.IsZero() {
		return false
	}
	return now.After(completed.Add(time.Duration(securityToolsJobTTLSeconds()) * time.Second))
}

func (r *SecurityToolRunReconciler) blobStore() (SecurityToolBlobReader, error) {
	if r.Blobs != nil {
		return r.Blobs, nil
	}
	return contentblob.NewS3FromEnv()
}

func securityToolOperatorEVMEnv() []corev1.EnvVar {
	var names []string
	for _, entry := range os.Environ() {
		name, value, found := strings.Cut(entry, "=")
		if !found || strings.TrimSpace(value) == "" {
			continue
		}
		if name == securityToolEVMForkEndpointsEnv ||
			strings.HasPrefix(name, securityToolEVMForkEndpointEnvPrefix) ||
			strings.HasPrefix(name, securityToolEVMUpstreamMirrorEnvPrefix) {
			names = append(names, name)
		}
	}
	slices.Sort(names)
	env := make([]corev1.EnvVar, 0, len(names))
	for _, name := range names {
		env = append(env, corev1.EnvVar{Name: name, Value: strings.TrimSpace(os.Getenv(name))})
	}
	return env
}

