func TestSecurityToolRunRefusesUnauthorizedNetworkTargets(t *testing.T) {
	t.Setenv(securityToolsImageEnv, securityToolTestImage)
	cases := []struct {
		name       string
		authorized string
		owner      bool
		mutate     func(*platformv1alpha1.SecurityToolRun)
		reason     string
		message    string
	}{
		{
			name:       "target outside the authorization",
			authorized: "api.example.test",
			owner:      true,
			mutate: func(run *platformv1alpha1.SecurityToolRun) {
				run.Spec.Target.Locator = "https://metadata.internal/latest/meta-data"
				run.Spec.Scope = []string{"https://metadata.internal/latest/meta-data"}
			},
			reason:  "NetworkTargetNotAuthorized",
			message: "not covered by the authorized network targets",
		},
		{
			name:       "scope entry outside the authorization",
			authorized: "api.example.test",
			owner:      true,
			mutate: func(run *platformv1alpha1.SecurityToolRun) {
				run.Spec.Scope = []string{"https://api.example.test/v1", "169.254.169.254"}
			},
			reason:  "NetworkTargetNotAuthorized",
			message: `"169.254.169.254" is not covered`,
		},
		{
			name:    "owner carries no authorization",
			owner:   true,
			reason:  "NetworkAuthorizationUnavailable",
			message: "carries no security.gratefulagents.dev/authorized-network-targets authorization",
		},
		{
			name:    "no owning agent run",
			mutate:  func(run *platformv1alpha1.SecurityToolRun) { run.OwnerReferences = nil },
			reason:  "NetworkAuthorizationUnavailable",
			message: "no owning AgentRun",
		},
		{
			name:    "owning agent run does not exist",
			reason:  "NetworkAuthorizationUnavailable",
			message: "does not exist",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			objects := []client.Object{newNetworkSecurityToolRun(tc.mutate)}
			if tc.owner {
				objects = append(objects, newScanAgentRun(tc.authorized))
			}
			c := newSecurityToolRunClient(t, objects...)

			run := reconcileSecurityToolRun(t, c, &stubBlobReader{})
			if run.Status.Phase != platformv1alpha1.SecurityToolRunPhaseFailed {
				t.Fatalf("phase = %q, want Failed", run.Status.Phase)
			}
			if run.Status.Result == nil || run.Status.Result.Status != "error" {
				t.Fatalf("result = %+v, want status error", run.Status.Result)
			}
			if !hasSecurityToolCondition(run, tc.reason) {
				t.Fatalf("conditions = %+v, want reason %s", run.Status.Conditions, tc.reason)
			}
			if !strings.Contains(run.Status.Message, tc.message) {
				t.Fatalf("message = %q, want it to contain %q", run.Status.Message, tc.message)
			}
			jobs := &batchv1.JobList{}
			if err := c.List(context.Background(), jobs, client.InNamespace("ns")); err != nil {
				t.Fatalf("List(Job) error = %v", err)
			}
			if len(jobs.Items) != 0 {
				t.Fatalf("jobs = %d, want no Job for an unauthorized network scan", len(jobs.Items))
			}
			configMaps := &corev1.ConfigMapList{}
			if err := c.List(context.Background(), configMaps, client.InNamespace("ns")); err != nil {
				t.Fatalf("List(ConfigMap) error = %v", err)
			}
			for _, item := range configMaps.Items {
				if item.Name == "scan-config" {
					t.Fatal("execution ConfigMap was created for an unauthorized network scan")
				}
			}
		})
	}
}

func (githubSkillFetcher) FetchSkillMD(ctx context.Context, src platformv1alpha1.SkillGitSource) (string, string, error) {
	owner, repo, err := parseGitHubRepoURL(src.URL)
	if err != nil {
		return "", "", err
	}
	skillPath := strings.Trim(strings.TrimSpace(src.Path), "/")
	if !strings.EqualFold(path.Base(skillPath), "SKILL.md") {
		skillPath = path.Join(skillPath, "SKILL.md")
	}
	opts := &github.RepositoryContentGetOptions{Ref: strings.TrimSpace(src.Ref)}
	client := github.NewClient(nil)
	if token := strings.TrimSpace(os.Getenv("GITHUB_TOKEN")); token != "" {
		client = client.WithAuthToken(token)
	}
	file, _, _, err := client.Repositories.GetContents(ctx, owner, repo, skillPath, opts)
	if err != nil {
		return "", "", fmt.Errorf("fetching %s/%s %s: %w", owner, repo, skillPath, err)
	}
	if file == nil {
		return "", "", fmt.Errorf("%s is a directory, expected a SKILL.md file", skillPath)
	}
	content, err := file.GetContent()
	if err != nil {
		return "", "", fmt.Errorf("decoding %s: %w", skillPath, err)
	}
	return content, file.GetSHA(), nil
}

func ensureSSHTunnelSidecar(podSpec *corev1.PodSpec, tunnel *platformv1alpha1.SSHTunnel) {
	if podSpec == nil || len(podSpec.Containers) == 0 || tunnel == nil {
		return
	}
	// Secret files default to 0644 root-owned; 0444 keeps them readable by
	// the sidecar's non-root uid. Only the sidecar mounts this volume, and it
	// re-copies the key to 0600 before ssh sees it (see sshTunnelCommand).
	secretMode := int32(0o444)
	podSpec.Volumes = append(podSpec.Volumes,
		corev1.Volume{
			Name: sshTunnelSecretVolume,
			VolumeSource: corev1.VolumeSource{Secret: &corev1.SecretVolumeSource{
				SecretName:  tunnel.Spec.SecretRef.Name,
				DefaultMode: &secretMode,
			}},
		},
		corev1.Volume{
			Name:         sshTunnelHomeVolume,
			VolumeSource: corev1.VolumeSource{EmptyDir: &corev1.EmptyDirVolumeSource{}},
		},
	)
	restartAlways := corev1.ContainerRestartPolicyAlways
	localPort := sshTunnelLocalPort(tunnel)
	podSpec.InitContainers = append(podSpec.InitContainers, corev1.Container{
		Name:            sshTunnelContainerName,
		Image:           firstNonEmpty(tunnel.Spec.Image, os.Getenv("SSH_TUNNEL_IMAGE"), defaultSSHTunnelImage),
		ImagePullPolicy: corev1.PullIfNotPresent,
		RestartPolicy:   &restartAlways,
		Command:         sshTunnelCommand(tunnel),
		Env:             []corev1.EnvVar{{Name: "HOME", Value: sshTunnelHomeDir}},
		SecurityContext: &corev1.SecurityContext{
			RunAsUser:                int64Ptr(sshTunnelRunAsUID),
			RunAsGroup:               int64Ptr(sshTunnelRunAsGID),
			RunAsNonRoot:             boolPtr(true),
			AllowPrivilegeEscalation: boolPtr(false),
			ReadOnlyRootFilesystem:   boolPtr(true),
			Capabilities:             &corev1.Capabilities{Drop: []corev1.Capability{"ALL"}},
			SeccompProfile:           &corev1.SeccompProfile{Type: corev1.SeccompProfileTypeRuntimeDefault},
		},
		VolumeMounts: []corev1.VolumeMount{
			{Name: sshTunnelSecretVolume, MountPath: sshTunnelSecretDir, ReadOnly: true},
			{Name: sshTunnelHomeVolume, MountPath: sshTunnelHomeDir},
		},
		// Gate the worker's start on the forward accepting connections so the
		// first model request does not race SSH session establishment. The
		// exec probe dials from inside the pod's network namespace, which is
		// the only place the loopback-bound forward is visible.
		StartupProbe: &corev1.Probe{
			ProbeHandler: corev1.ProbeHandler{Exec: &corev1.ExecAction{
				Command: []string{"/bin/sh", "-c", fmt.Sprintf("nc -z 127.0.0.1 %d", localPort)},
			}},
			PeriodSeconds:    2,
			FailureThreshold: 60,
		},
		Ports: []corev1.ContainerPort{{Name: "openai", ContainerPort: localPort, Protocol: corev1.ProtocolTCP}},
	})

	worker := &podSpec.Containers[0]
	upsertContainerEnv(worker, corev1.EnvVar{Name: "OPENAI_BASE_URL", Value: sshTunnelBaseURL(tunnel)})
}

func TestEnsureSSHTunnelSidecar(t *testing.T) {
	run := &platformv1alpha1.AgentRun{
		ObjectMeta: metav1.ObjectMeta{Name: "run", Namespace: "ns"},
		Spec: platformv1alpha1.AgentRunSpec{
			OpenAIBaseURL: "https://api.openai.com/v1",
		},
	}
	tunnel := testSSHTunnel()
	podSpec := buildCommonPodSpec(run, "sa", []string{"/bin/agent"}, nil, nil, nil)
	ensureSSHTunnelSidecar(&podSpec, tunnel)

	var sidecar *corev1.Container
	for i := range podSpec.InitContainers {
		if podSpec.InitContainers[i].Name == sshTunnelContainerName {
			sidecar = &podSpec.InitContainers[i]
		}
	}
	if sidecar == nil {
		t.Fatalf("ssh-tunnel sidecar not found in init containers: %+v", podSpec.InitContainers)
	}
	if sidecar.RestartPolicy == nil || *sidecar.RestartPolicy != corev1.ContainerRestartPolicyAlways {
		t.Fatal("sidecar must be a native sidecar (restartPolicy Always)")
	}
	script := strings.Join(sidecar.Command, " ")
	for _, want := range []string{
		"StrictHostKeyChecking=yes",
		"ExitOnForwardFailure=yes",
		"BatchMode=yes",
		"IdentitiesOnly=yes",
		"-L 127.0.0.1:8434:127.0.0.1:8000",
		"-p 22",
		"tunnel@inference.example.com",
		"UserKnownHostsFile=/etc/ssh-tunnel/known_hosts",
	} {
		if !strings.Contains(script, want) {
			t.Fatalf("ssh command missing %q: %s", want, script)
		}
	}

	// Hardened sidecar security context.
	sc := sidecar.SecurityContext
	if sc == nil || sc.RunAsNonRoot == nil || !*sc.RunAsNonRoot ||
		sc.ReadOnlyRootFilesystem == nil || !*sc.ReadOnlyRootFilesystem ||
		sc.AllowPrivilegeEscalation == nil || *sc.AllowPrivilegeEscalation ||
		sc.Capabilities == nil || len(sc.Capabilities.Drop) != 1 || sc.Capabilities.Drop[0] != "ALL" {
		t.Fatalf("sidecar security context not hardened: %+v", sc)
	}

	// The worker's OPENAI_BASE_URL must point at the loopback forward.
	worker := podSpec.Containers[0]
	var baseURL string
	for _, env := range worker.Env {
		if env.Name == "OPENAI_BASE_URL" {
			baseURL = env.Value
		}
	}
	if baseURL != "http://127.0.0.1:8434/v1" {
		t.Fatalf("worker OPENAI_BASE_URL = %q, want tunnel loopback URL", baseURL)
	}

	// The key volume must be mounted only in the sidecar, never the worker.
	for _, mount := range worker.VolumeMounts {
		if mount.Name == sshTunnelSecretVolume {
			t.Fatal("tunnel secret volume must not be mounted into the worker container")
		}
	}
	foundSecretMount := false
	for _, mount := range sidecar.VolumeMounts {
		if mount.Name == sshTunnelSecretVolume && mount.ReadOnly {
			foundSecretMount = true
		}
	}
	if !foundSecretMount {
		t.Fatal("tunnel secret volume must be mounted read-only into the sidecar")
	}
}

func (h *GitHubAppWebhookHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	log := logf.FromContext(ctx).WithName("github-app-webhook")

	inner := h.Inner
	if inner == nil || inner.Reconciler == nil {
		http.Error(w, "webhook handler not configured", http.StatusInternalServerError)
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, maxWebhookBodyBytes))
	if err != nil {
		http.Error(w, "failed to read body", http.StatusBadRequest)
		return
	}

	// Validate the app-level webhook secret. App deliveries are signed once
	// with the App's secret; per-CR spec.webhookSecret does not apply here.
	if h.WebhookSecretName != "" {
		secret := &corev1.Secret{}
		if err := inner.Client.Get(ctx, types.NamespacedName{
			Namespace: h.WebhookSecretNamespace,
			Name:      h.WebhookSecretName,
		}, secret); err != nil {
			log.Error(err, "failed to read app webhook secret", "secret", h.WebhookSecretName)
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		secretValue, ok := secret.Data["secret"]
		if !ok {
			log.Error(nil, "app webhook secret missing 'secret' key", "secret", h.WebhookSecretName)
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		if !validateGitHubSignature(body, r.Header.Get("X-Hub-Signature-256"), secretValue) {
			http.Error(w, "invalid signature", http.StatusUnauthorized)
			return
		}
	} else {
		if !h.AllowUnauthenticated {
			log.Error(nil, "GITHUB_APP_WEBHOOK_SECRET not configured — rejecting unauthenticated app webhook",
				"namespace", h.WebhookSecretNamespace, "secretEnv", "GITHUB_APP_WEBHOOK_SECRET")
			http.Error(w, "webhook secret not configured", http.StatusUnauthorized)
			return
		}
		log.Error(nil, "GITHUB_APP_WEBHOOK_SECRET not configured — accepting unauthenticated app webhook",
			"namespace", h.WebhookSecretNamespace, "secretEnv", "GITHUB_APP_WEBHOOK_SECRET")
	}

	inner.dedupOnce.Do(func() { inner.dedup = newDeliveryDeduper() })
	if inner.dedup.isDuplicate(r.Header.Get("X-GitHub-Delivery")) {
		w.WriteHeader(http.StatusOK)
		return
	}

	var envelope githubRepositoryEnvelope
	if err := json.Unmarshal(body, &envelope); err != nil {
		http.Error(w, "invalid payload", http.StatusBadRequest)
		return
	}
	fullName := strings.TrimSpace(envelope.Repository.FullName)
	if fullName == "" {
		// Non-repository events (installation lifecycle, ping, …) are fine.
		w.WriteHeader(http.StatusOK)
		return
	}

	matches, err := h.matchingRepositories(r, fullName)
	if err != nil {
		log.Error(err, "failed to list GitHubRepositories", "repository", fullName)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	eventType := r.Header.Get("X-GitHub-Event")
	if len(matches) == 0 {
		// Trigger-independent PR loop fallback. Non-PR events still require a
		// GitHubRepository because issue triggering needs repository policy.
		if isPullRequestWebhookEvent(eventType) && inner.PRSink != nil {
			writeWebhookResult(w, inner.dispatchEvent(ctx, nil, eventType, body))
			return
		}
		w.WriteHeader(http.StatusOK)
		return
	}

	var dispatchErr error
	for i := range matches {
		gh := &matches[i]
		if err := inner.dispatchEvent(ctx, gh, eventType, body); err != nil {
			log.Error(err, "app webhook dispatch failed",
				"repository", fullName, "namespace", gh.Namespace, "name", gh.Name, "event", eventType)
			dispatchErr = err
		}
	}
	writeWebhookResult(w, dispatchErr)
}

func (e *securityScanExecutionEngine) observePostScripts(ctx context.Context) {
	for i := range e.exec.PostScriptJobs {
		job := &e.exec.PostScriptJobs[i]
		if job.State != triggersv1alpha1.SecurityScanPostScriptStateRunning {
			continue
		}
		run, err := e.getRun(ctx, job.RunName)
		if err != nil {
			continue // transient read error: retry next reconcile
		}
		if run == nil {
			e.recordPostScriptFailure(job, "post-script run disappeared before completing", triggersv1alpha1.SecurityScanTaskFailureRetryable)
			continue
		}
		// Paused is published before the AgentRun controller drains the old
		// sandbox. Keep the pipeline and sink gated until that worker can no
		// longer mutate the finding during shutdown.
		if run.Status.Phase == platformv1alpha1.AgentRunPhasePaused && run.Status.Sandbox != nil {
			continue
		}
		switch run.Status.Phase {
		case platformv1alpha1.AgentRunPhaseSucceeded:
			if reason, class := e.confirmedReportWriterArtifactFailure(ctx, job); reason != "" {
				if class == "pending" {
					// The model run is already successful. A transient store read
					// must not spend another model attempt or duplicate post-script
					// side effects; leave the job Running and verify again later.
					job.LastError = truncateSecurityScanError(reason)
					continue
				}
				e.recordPostScriptFailure(job, reason, class)
				continue
			}
			if disposition := e.postScriptRetryableDisposition(ctx, job); disposition != "" {
				if job.Attempts < 1+e.resolved.spec.EffectivePostScriptMaxEnvRetries() {
					job.State = triggersv1alpha1.SecurityScanPostScriptStatePending
					job.LastError = truncateSecurityScanError(fmt.Sprintf("policy disposition %s: the environment could not run the validation; retrying", disposition))
					continue
				}
				job.State = triggersv1alpha1.SecurityScanPostScriptStateSucceeded
				job.LastError = ""
				job.FinishedAt = &e.now
				job.Result = truncateSecurityScanError(fmt.Sprintf("%s; policy disposition %s stands after %d attempt(s)", e.postScriptVerdict(ctx, job), disposition, job.Attempts))
				appendSecurityScanCoverageGap(e.exec, securityScanPostScriptJobGapPrefix(securityScanPostScriptJobLabel(*job), job.Fingerprint)+fmt.Sprintf("the environment could not run the validation (policy disposition %s) in %d attempt(s)", disposition, job.Attempts))
				continue
			}
			job.State = triggersv1alpha1.SecurityScanPostScriptStateSucceeded
			job.LastError = ""
			job.FinishedAt = &e.now
			job.Result = truncateSecurityScanError(e.postScriptVerdict(ctx, job))
		case platformv1alpha1.AgentRunPhaseFailed, platformv1alpha1.AgentRunPhaseCancelled:
			reason := securityScanAgentRunFailureReason(run, "post-script")
			e.recordPostScriptFailure(job, reason, classifySecurityScanTaskFailure(reason))
		case platformv1alpha1.AgentRunPhasePaused:
			// A pause requires a limit change to resume. Retrying the same
			// immutable scan attempt would carry the same exhausted limit and,
			// because Paused has no completion timestamp, bypass retry backoff.
			e.recordPostScriptFailure(job, securityScanAgentRunFailureReason(run, "post-script"),
				triggersv1alpha1.SecurityScanTaskFailureNonRetryable)
			e.releasePausedRun(ctx, run)
		}
	}
}

func TestSecurityScanPostScriptRetriesUnreproducibleEnvironment(t *testing.T) {
	for _, tc := range []struct {
		name          string
		disposition   string
		maxEnvRetries *int32
		wantRetry     bool
	}{
		{name: "unreproducible_env retries by default", disposition: "unreproducible_env", wantRetry: true},
		{name: "not_ready retries by default", disposition: "not_ready", wantRetry: true},
		{name: "maxEnvRetries zero stands", disposition: "unreproducible_env", maxEnvRetries: new(int32), wantRetry: false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			now := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
			clock := now
			scan := postScriptSecurityScan([]triggersv1alpha1.SecurityScanPostScript{{
				Name: "poc-validator", Prompt: "Rerun the PoC.", RunOn: "low-and-above-actionable",
			}}, 2)
			scan.Spec.Execution.RetryBackoff = metav1.Duration{Duration: time.Second}
			scan.Spec.Execution.MaxEnvRetries = tc.maxEnvRetries
			reconciler, k8sClient, _ := newDeterministicSecurityScanReconciler(t, now, scan)
			finding := postScriptTestFinding("00000000-0000-0000-0000-0000000000a1", "fp-alpha", "critical")
			finding.Status = store.SecurityFindingStatusTriaged
			findings := &postScriptFindingStore{findings: []store.SecurityFindingRecord{finding}}
			reconciler.Findings = findings
			reconciler.Now = func() time.Time { return clock }

			reconcileDeterministicSecurityScan(t, reconciler, scan)
			research := taskRunByTask(t, securityScanRuns(t, k8sClient, scan.Namespace), "research")
			markSecurityScanTaskRun(t, k8sClient, scan.Namespace, research.Name, platformv1alpha1.AgentRunPhaseSucceeded, "", "")
			reconcileDeterministicSecurityScan(t, reconciler, scan)
			reconcileDeterministicSecurityScan(t, reconciler, scan)

			exec := getSecurityScan(t, k8sClient, scan).Status.LastExecution
			run := postScriptRun(t, securityScanRuns(t, k8sClient, scan.Namespace), "poc-validator", finding.Fingerprint)
			findings.events = []store.SecurityFindingEvent{{
				FindingID: finding.ID, EventType: "policy_disposition", Actor: run.Name,
				Detail: json.RawMessage(`{"execution_id":"` + exec.ID + `","policy_check":"reproduction","policy_disposition":"` + tc.disposition + `"}`),
			}}
			markSecurityScanTaskRun(t, k8sClient, scan.Namespace, run.Name, platformv1alpha1.AgentRunPhaseSucceeded, "", "")
			reconcileDeterministicSecurityScan(t, reconciler, scan)

			exec = getSecurityScan(t, k8sClient, scan).Status.LastExecution
			job := postScriptJob(t, exec, finding.Fingerprint)
			if !tc.wantRetry {
				if job.State != triggersv1alpha1.SecurityScanPostScriptStateSucceeded || job.Attempts != 1 || !strings.Contains(job.Result, tc.disposition) {
					t.Fatalf("job = %#v, want Succeeded with the disposition in the result", job)
				}
				if !strings.Contains(strings.Join(exec.CoverageGaps, "\n"), tc.disposition) {
					t.Fatalf("coverage gaps = %#v, want the environment failure disclosed", exec.CoverageGaps)
				}
				return
			}
			// The fake client stamps no creation time on the finished run, so the
			// backoff derived from it has already elapsed and the retry may
			// have been launched within the same pass.
			if !strings.Contains(job.LastError, tc.disposition) {
				t.Fatalf("job = %#v, want the disposition recorded as the retry reason", job)
			}
			if job.State == triggersv1alpha1.SecurityScanPostScriptStatePending {
				if job.Attempts != 1 {
					t.Fatalf("job = %#v, want a queued retry", job)
				}
				clock = clock.Add(2 * time.Second)
				reconcileDeterministicSecurityScan(t, reconciler, scan)
				job = postScriptJob(t, getSecurityScan(t, k8sClient, scan).Status.LastExecution, finding.Fingerprint)
			}
			if job.State != triggersv1alpha1.SecurityScanPostScriptStateRunning || job.Attempts != 2 || job.RunName == run.Name {
				t.Fatalf("job = %#v, want a second attempt running", job)
			}
			if len(exec.CoverageGaps) != 0 {
				t.Fatalf("coverage gaps = %#v, want none while a retry is pending", exec.CoverageGaps)
			}

			// A verdict from the retry ends the job even though the older
			// environment disposition is still in the audit trail.
			retry := getAgentRun(t, k8sClient, scan.Namespace, job.RunName)
			findings.events = append([]store.SecurityFindingEvent{{
				FindingID: finding.ID, EventType: "policy_disposition", Actor: retry.Name,
				Detail: json.RawMessage(`{"execution_id":"` + exec.ID + `","policy_check":"reproduction","policy_disposition":"reproduced"}`),
			}}, findings.events...)
			markSecurityScanTaskRun(t, k8sClient, scan.Namespace, retry.Name, platformv1alpha1.AgentRunPhaseSucceeded, "", "")
			reconcileDeterministicSecurityScan(t, reconciler, scan)
			job = postScriptJob(t, getSecurityScan(t, k8sClient, scan).Status.LastExecution, finding.Fingerprint)
			if job.State != triggersv1alpha1.SecurityScanPostScriptStateSucceeded || job.Attempts != 2 {
				t.Fatalf("job after retry verdict = %#v, want Succeeded", job)
			}
		})
	}
}

func writeSecurityProgramTypedScope(b *strings.Builder, program *triggersv1alpha1.SecurityProgramSpec) {
	if program == nil {
		return
	}
	if strings.TrimSpace(program.SeveritySystem) != "" {
		fmt.Fprintf(b, "- Severity system: %q. Rank every finding with this system's own table and never translate a severity label from another system into it.\n", program.SeveritySystem)
	}
	if strings.TrimSpace(program.Primacy) != "" {
		switch program.Primacy {
		case string(triggersv1alpha1.PrimacyImpact):
			b.WriteString("- Primacy: impact. A demonstrated in-scope impact counts even when the affected asset is not itemized.\n")
		default:
			b.WriteString("- Primacy: rules. Only the itemized assets are eligible, whatever the impact.\n")
		}
	}
	if program.PoCRequired {
		environment := strings.TrimSpace(program.PoCEnvironment)
		if environment == "" {
			environment = "unspecified"
		}
		fmt.Fprintf(b, "- Proof of concept: required (%s). A report without a runnable proof is not eligible.\n", environment)
	}
	if len(program.InScopeImpacts) != 0 {
		b.WriteString("- In-scope impacts. Select the report's impact verbatim from this list; never invent an impact or asset:\n")
		for _, impact := range program.InScopeImpacts {
			if assetType := strings.TrimSpace(impact.AssetType); assetType != "" {
				fmt.Fprintf(b, "  - [%s] %q (asset type %q)\n", impact.Level, impact.Impact, assetType)
				continue
			}
			fmt.Fprintf(b, "  - [%s] %q\n", impact.Level, impact.Impact)
		}
	}
	if len(program.OutOfScope) != 0 {
		b.WriteString("- Out of scope (verbatim exclusions):\n")
		for _, exclusion := range program.OutOfScope {
			fmt.Fprintf(b, "  - %q\n", exclusion)
		}
	}
	if len(program.KnownIssues) != 0 {
		b.WriteString("- Known issues. These, and findings sharing their root cause, are not reportable:\n")
		for _, issue := range program.KnownIssues {
			fmt.Fprintf(b, "  - %q (source %q)\n", issue.Summary, issue.Source)
		}
	}
	if len(program.ProhibitedTesting) != 0 {
		b.WriteString("- Prohibited testing (violating these forfeits every report):\n")
		for _, prohibited := range program.ProhibitedTesting {
			fmt.Fprintf(b, "  - %q\n", prohibited)
		}
	}
	if len(program.Assets) != 0 {
		b.WriteString("- Deployed assets in scope:\n")
		for _, asset := range program.Assets {
			switch {
			case asset.Address != "":
				fmt.Fprintf(b, "  - chain %q address %q\n", asset.ChainID, asset.Address)
			case asset.RepositoryURL != "":
				fmt.Fprintf(b, "  - repository %q\n", asset.RepositoryURL)
			}
		}
	}
	if budget := program.SubmissionBudget; budget != nil && budget.MaxPerPeriod > 0 {
		if budget.PeriodDays > 0 {
			fmt.Fprintf(b, "- Submission budget: at most %d reports per %d days. Reporting is rationed: submit only the strongest findings.\n", budget.MaxPerPeriod, budget.PeriodDays)
		} else {
			fmt.Fprintf(b, "- Submission budget: at most %d reports. Reporting is rationed: submit only the strongest findings.\n", budget.MaxPerPeriod)
		}
	}
	if len(program.InScopeImpacts) != 0 || strings.TrimSpace(program.SeveritySystem) != "" {
		b.WriteString("\n")
	}
}

func TestSecurityProgramTypedScopeIsRenderedInEveryPrompt(t *testing.T) {
	spec := securityScanPromptSpec()
	program := &triggersv1alpha1.SecurityProgramSpec{
		Provider:       "Immunefi",
		DisplayName:    "Acme Program",
		ProgramURL:     "https://immunefi.com/bug-bounty/acme",
		ScopePolicy:    "The acme/widget repository is in scope.",
		VerifiedAt:     metav1.NewTime(time.Date(2026, 8, 1, 12, 0, 0, 0, time.UTC)),
		SeveritySystem: string(triggersv1alpha1.SeveritySystemImmunefiV23),
		Primacy:        string(triggersv1alpha1.PrimacyImpact),
		PoCRequired:    true,
		PoCEnvironment: string(triggersv1alpha1.PoCEnvironmentMainnetFork),
		InScopeImpacts: []triggersv1alpha1.SecurityProgramImpact{
			{Impact: "Permanent freezing of funds", Level: "critical", AssetType: "Smart Contract"},
		},
		OutOfScope:        []string{"Attacks requiring leaked keys"},
		ProhibitedTesting: []string{"Testing on mainnet or public testnet"},
		KnownIssues: []triggersv1alpha1.SecurityProgramKnownIssue{
			{Source: "prior audit", Summary: "Rounding in withdraw is acknowledged"},
		},
		Assets: []triggersv1alpha1.SecurityProgramAsset{
			{ChainID: "1", Address: "0xabc"},
		},
		SubmissionBudget: &triggersv1alpha1.SecurityProgramSubmissionBudget{MaxPerPeriod: 2, PeriodDays: 30},
	}
	task := spec.Workflow[0]
	finding := SecurityPostScriptFinding{Fingerprint: "fp", ID: "id", Title: "finding", Severity: "high", Status: "open"}
	prompts := map[string]string{
		"coordinator": BuildSecurityScanPromptWithProgram(spec, nil, 0, program),
		"task":        BuildSecurityScanTaskPromptWithProgram(spec, nil, task, SecurityScanTaskInstance{}, nil, program),
		"post-script": BuildSecurityPostScriptPipelinePromptWithProgram(spec, nil, spec.PostScripts, finding, program),
	}
	for name, prompt := range prompts {
		t.Run(name, func(t *testing.T) {
			for _, want := range []string{
				`Severity system: "immunefi-v2.3"`,
				"never translate a severity label",
				"Primacy: impact",
				"Proof of concept: required (mainnet-fork)",
				"Select the report's impact verbatim",
				`[critical] "Permanent freezing of funds" (asset type "Smart Contract")`,
				`"Attacks requiring leaked keys"`,
				`"Rounding in withdraw is acknowledged"`,
				`"Testing on mainnet or public testnet"`,
				`chain "1" address "0xabc"`,
				"at most 2 reports per 30 days",
			} {
				if !strings.Contains(prompt, want) {
					t.Fatalf("prompt missing %q:\n%s", want, prompt)
				}
			}
		})
	}

	// A program without typed scope renders none of the typed section.
	untyped := &triggersv1alpha1.SecurityProgramSpec{
		Provider:    "HackerOne",
		DisplayName: "Legacy Program",
		ProgramURL:  "https://hackerone.com/acme",
		ScopePolicy: "The acme/widget repository is in scope.",
		VerifiedAt:  metav1.NewTime(time.Date(2026, 8, 1, 12, 0, 0, 0, time.UTC)),
	}
	prompt := BuildSecurityScanPromptWithProgram(spec, nil, 0, untyped)
	for _, unwanted := range []string{"Severity system:", "In-scope impacts", "Submission budget:"} {
		if strings.Contains(prompt, unwanted) {
			t.Fatalf("untyped program rendered %q:\n%s", unwanted, prompt)
		}
	}
}

