		created.GetGitRemoteWrites() != string(platformv1alpha1.GitRemoteWritesDisabled) {
		t.Fatalf("Git remote writes did not round-trip: saved=%#v created=%q", saved.Spec.Security, created.GetGitRemoteWrites())
	}
	if saved.Spec.Resources == nil || saved.Spec.Resources.Requests.Cpu().String() != "500m" || saved.Spec.Resources.Limits.Memory().String() != "2Gi" {
		t.Fatalf("saved resources = %#v, want requests and limits", saved.Spec.Resources)
	}
	if saved.Spec.Admission == nil || saved.Spec.Admission.MaxConcurrentRuns != 4 || saved.Spec.Admission.PerNamespaceMaxConcurrentRuns != 2 || saved.Spec.Admission.StaleRunTimeout.Duration != 30*time.Minute {
		t.Fatalf("saved admission = %#v, want all concurrency values", saved.Spec.Admission)
	}
	if !created.EnablePrivateProcfs || created.SandboxTemplateRef != "browser-template" || created.CommandEnv["LANG"] != "C.UTF-8" || created.ResourceRequests["cpu"] != "500m" || created.MaxConcurrentRuns != 4 {
		t.Fatalf("created profile did not round-trip all fields: %#v", created)
	}
	if len(created.ExtraWritablePaths) != 2 || created.ExtraWritablePaths[1] != "/cache/npm" {
		t.Fatalf("created writable paths = %#v", created.ExtraWritablePaths)
	}
	other, err := srv.ListRuntimeProfiles(resourceActorContext("bob-id", "member", "Bob Jones"), &platform.ListRuntimeProfilesRequest{})
	if err != nil {
		t.Fatalf("ListRuntimeProfiles() error = %v", err)
	}
	if len(other.Profiles) != 0 {
		t.Fatalf("other user saw %d profiles", len(other.Profiles))
	}
	_, err = srv.CreateMCPPolicy(ctx, &platform.CreateMCPPolicyRequest{Policy: &platform.MCPPolicy{Namespace: "another-tenant", Name: "deny-all", DefaultAction: "Deny"}})
	if connect.CodeOf(err) != connect.CodeInvalidArgument {
		t.Fatalf("caller-selected namespace: want InvalidArgument, got %v", err)
	}
}

const (
	// runtimeImageCatalogConfigMapEnv names the ConfigMap (in the manager
	// namespace) that overrides the built-in worker image catalog.
	runtimeImageCatalogConfigMapEnv     = "RUNTIME_IMAGE_CATALOG_CONFIGMAP"
	defaultRuntimeImageCatalogConfigMap = "runtime-image-catalog"
	runtimeImageCatalogKey              = "catalog.yaml"
)

func (s *Server) ListRuntimeImages(ctx context.Context, _ *platform.ListRuntimeImagesRequest) (*platform.ListRuntimeImagesResponse, error) {
	return &platform.ListRuntimeImagesResponse{Images: s.runtimeImageCatalog(ctx)}, nil
}

func (s *Server) runtimeImageCatalog(ctx context.Context) []*platform.RuntimeImageOption {
	namespace := strings.TrimSpace(os.Getenv("POD_NAMESPACE"))
	if namespace == "" || s.k8sClient == nil {
		return builtinRuntimeImageCatalog()
	}
	name := strings.TrimSpace(os.Getenv(runtimeImageCatalogConfigMapEnv))
	if name == "" {
		name = defaultRuntimeImageCatalogConfigMap
	}
	cm := &corev1.ConfigMap{}
	if err := s.k8sClient.Get(ctx, types.NamespacedName{Namespace: namespace, Name: name}, cm); err != nil {
		// Absent ConfigMap is the normal "no override" case; other errors are
		// worth a warning but never break the picker.
		if !apierrors.IsNotFound(err) {
			log.Printf("WARN: reading runtime image catalog ConfigMap %s/%s: %v", namespace, name, err)
		}
		return builtinRuntimeImageCatalog()
	}
	options, err := parseRuntimeImageCatalog([]byte(cm.Data[runtimeImageCatalogKey]))
	if err != nil {
		log.Printf("WARN: invalid runtime image catalog in ConfigMap %s/%s: %v; using built-in catalog", namespace, name, err)
		return builtinRuntimeImageCatalog()
	}
	return options
}

func (s *Server) loadSecurityCatalog(ctx context.Context, destinationNamespace string) (*securityCatalogSnapshot, error) {
	snapshot := &securityCatalogSnapshot{items: map[securityCatalogKey]*securityCatalogItem{}}
	sourceNamespace := strings.TrimSpace(os.Getenv("POD_NAMESPACE"))
	if sourceNamespace == "" {
		snapshot.readyMessage = "POD_NAMESPACE is not configured"
		snapshot.revision = securityCatalogRevision("", "", snapshot.items)
		return snapshot, nil
	}
	bundleVersion, bundleReady, err := bootstrapBundleVersion(ctx, s.apiReaderOrClient(), sourceNamespace)
	if err != nil {
		return nil, err
	}
	snapshot.ready = bundleReady
	if !bundleReady {
		snapshot.readyMessage = "the shipped security catalog is not ready"
	}
	if err := s.listSecurityCatalogSources(ctx, sourceNamespace, snapshot); err != nil {
		return nil, err
	}
	for _, item := range snapshot.items {
		state, err := s.securityCatalogInstallState(ctx, destinationNamespace, item.source)
		if err != nil {
			return nil, err
		}
		item.state = state
		for _, dependency := range item.dependencies {
			if dependency.required && snapshot.items[dependency.key] == nil {
				item.ready = false
				item.readyMessage = fmt.Sprintf("required dependency %s/%s is missing from the catalog", securityCatalogKindName(dependency.key.kind), dependency.key.name)
			}
		}
		snapshot.ordered = append(snapshot.ordered, item)
	}
	sort.Slice(snapshot.ordered, func(i, j int) bool {
		if snapshot.ordered[i].key.kind != snapshot.ordered[j].key.kind {
			return snapshot.ordered[i].key.kind < snapshot.ordered[j].key.kind
		}
		return snapshot.ordered[i].key.name < snapshot.ordered[j].key.name
	})
	snapshot.revision = securityCatalogRevision(bundleVersion, sourceNamespace, snapshot.items)
	return snapshot, nil
}

