	if len(pb.GetKnownIssues()) != 1 || pb.GetKnownIssues()[0].GetSource() != "prior audit" ||
		pb.GetKnownIssues()[0].GetSummary() != "Acknowledged rounding" ||
		pb.GetKnownIssues()[0].GetReference() != "https://acme.example/audit.pdf" {
