func (s *Server) GetSecurityFindingSubmissionBundle(ctx context.Context, req *platform.GetSecurityFindingSubmissionBundleRequest) (*platform.GetSecurityFindingSubmissionBundleResponse, error) {
	sec, err := s.securityStore()
	if err != nil {
		return nil, err
	}
	finding, err := s.authorizedSecurityFinding(ctx, sec, req.GetFindingId(), req.GetNamespace(), "")
	if err != nil {
		return nil, err
	}
	artifacts, ok := sec.(store.SecurityFindingArtifactStore)
	if !ok {
		return &platform.GetSecurityFindingSubmissionBundleResponse{Status: "unavailable"}, nil
	}
	artifact, err := artifacts.GetSecurityFindingArtifact(ctx, finding.Namespace, finding.ID, finding.ExecutionID, store.SecurityFindingArtifactSubmissionBundle)
	if err != nil {
		return nil, connect.NewError(connect.CodeInternal, fmt.Errorf("getting submission bundle metadata: %w", err))
	}
	if artifact == nil {
		return &platform.GetSecurityFindingSubmissionBundleResponse{Status: "unavailable"}, nil
	}
	resp := &platform.GetSecurityFindingSubmissionBundleResponse{
		Status: artifact.Status, Error: artifact.Error, Filename: artifact.Filename,
		Sha256: artifact.SHA256, SizeBytes: artifact.SizeBytes,
	}
	if !artifact.CreatedAt.IsZero() {
		resp.CreatedAt = timestamppb.New(artifact.CreatedAt)
	}
	if artifact.Status != "ready" {
		if resp.Status == "" {
			resp.Status = "generating"
		}
		return resp, nil
	}
	if s.s3Reader == nil || s.s3Reader.client == nil {
		resp.Status, resp.Error = "error", "private artifact storage is unavailable"
		return resp, nil
	}
	bucket := strings.TrimSpace(os.Getenv("S3_BUCKET"))
	prefix := "security-submissions/v1/" + finding.Namespace + "/"
	if bucket == "" || !strings.HasPrefix(artifact.S3Key, prefix) || strings.Contains(artifact.S3Key, "..") {
		resp.Status, resp.Error = "error", "stored bundle reference is invalid"
		return resp, nil
	}
	if artifact.SizeBytes <= 0 || artifact.SizeBytes > maxSecuritySubmissionBundleBytes {
		resp.Status, resp.Error = "error", "stored bundle size is invalid"
		return resp, nil
	}
	output, err := s.s3Reader.client.GetObject(ctx, &s3.GetObjectInput{Bucket: aws.String(bucket), Key: aws.String(artifact.S3Key)})
	if err != nil {
		resp.Status, resp.Error = "error", "private bundle could not be fetched"
		return resp, nil
	}
	body, readErr := io.ReadAll(io.LimitReader(output.Body, maxSecuritySubmissionBundleBytes+1))
	closeErr := output.Body.Close()
	if readErr != nil || closeErr != nil || int64(len(body)) > maxSecuritySubmissionBundleBytes || int64(len(body)) != artifact.SizeBytes {
		resp.Status, resp.Error = "error", "private bundle failed bounded read verification"
		return resp, nil
	}
	digest := sha256.Sum256(body)
	if !strings.EqualFold(hex.EncodeToString(digest[:]), artifact.SHA256) {
		resp.Status, resp.Error = "error", "private bundle checksum verification failed"
		return resp, nil
	}
	resp.Content = body
	return resp, nil
}

func securityScanSpecToProto(spec *triggersv1alpha1.SecurityScanSpec) *platform.SecurityScanConfigSpec {
	pb := &platform.SecurityScanConfigSpec{
		RepoUrl:           spec.RepoURL,
		TargetUrl:         spec.TargetURL,
		BaseBranch:        spec.BaseBranch,
		Revision:          spec.Revision,
		AdditionalRepos:   append([]string(nil), spec.AdditionalRepos...),
		Parallelism:       spec.Parallelism,
		MinSeverity:       spec.MinSeverity,
		FailOnSeverity:    spec.FailOnSeverity,
		ManualOnly:        spec.ManualOnly,
		Schedule:          spec.Schedule,
		TimeZone:          spec.TimeZone,
		Suspend:           spec.Suspend,
		ConcurrencyPolicy: string(spec.ConcurrencyPolicy),
		Defaults:          crdDefaultsToProto(spec.Defaults),
	}
	pb.Defaults.DockerInDocker = &spec.Defaults.DockerInDocker
	if spec.MaxRuntime.Duration != 0 {
		pb.MaxRuntime = spec.MaxRuntime.Duration.String()
	}
	pb.Budgets = securityScanBudgetsToProto(spec.Budgets)
	if spec.WorkflowRef != nil {
		pb.WorkflowRef = spec.WorkflowRef.Name
	}
	for _, ref := range spec.RankerRefs {
		pb.RankerRefs = append(pb.RankerRefs, ref.Name)
	}
	for _, ref := range spec.PostScriptRefs {
		pb.PostScriptRefs = append(pb.PostScriptRefs, ref.Name)
	}
	if spec.PolicyPackRef != nil {
		pb.PolicyPackRef = spec.PolicyPackRef.Name
	}
	if spec.SecurityProgramRef != nil {
		pb.SecurityProgramRef = spec.SecurityProgramRef.Name
	}
	if scope := spec.Scope; scope != nil {
		pb.Scope = &platform.SecurityScanScopeConfig{
			Focus:                    scope.Focus,
			IncludePaths:             append([]string(nil), scope.IncludePaths...),
			ExcludePaths:             append([]string(nil), scope.ExcludePaths...),
			Languages:                append([]string(nil), scope.Languages...),
			AuthorizedNetworkTargets: append([]string(nil), scope.AuthorizedNetworkTargets...),
		}
	}
	for _, t := range spec.Workflow {
		pb.Workflow = append(pb.Workflow, securityScanTaskToProto(t))
	}
	if e := spec.Execution; e != nil {
		pb.Execution = &platform.SecurityScanExecutionConfig{Mode: e.Mode}
		if e.TaskMaxRetries != nil {
			retries := *e.TaskMaxRetries
			pb.Execution.TaskMaxRetries = &retries
		}
		if e.RetryBackoff.Duration != 0 {
			pb.Execution.RetryBackoff = e.RetryBackoff.Duration.String()
		}
		if e.MaxEnvRetries != nil {
			retries := *e.MaxEnvRetries
			pb.Execution.MaxEnvRetries = &retries
		}
	}
	if len(spec.ParameterValues) != 0 {
		pb.ParameterValues = make(map[string]string, len(spec.ParameterValues))
		maps.Copy(pb.ParameterValues, spec.ParameterValues)
	}
	for _, r := range spec.SeverityRankers {
		pb.SeverityRankers = append(pb.SeverityRankers, &platform.SecurityRankerConfig{Name: r.Name, Rules: r.Rules})
	}
	for _, p := range spec.PostScripts {
		pb.PostScripts = append(pb.PostScripts, &platform.SecurityPostScriptConfig{
			Name: p.Name, Prompt: p.Prompt, RunOn: p.RunOn,
		})
	}
	if d := spec.Dedupe; d != nil {
		pb.Dedupe = &platform.SecurityScanDedupeConfig{
			Enabled:                     d.Enabled == nil || *d.Enabled,
			SimilarityThresholdPermille: d.SimilarityThresholdPermille,
		}
	}
	if t := spec.Triggers; t != nil {
		pb.Triggers = &platform.SecurityScanTriggersConfig{
			OnPullRequest: t.OnPullRequest,
			OnPush:        t.OnPush,
			Branches:      append([]string(nil), t.Branches...),
			DiffScope:     t.DiffScope,
			AllowForks:    t.AllowForks,
		}
		if t.RepositoryRef != nil {
			pb.Triggers.RepositoryRef = t.RepositoryRef.Name
		}
	}
	if c := spec.Checks; c != nil {
		pb.Checks = &platform.SecurityScanChecksConfig{
			Enabled:                 c.Enabled,
			IncludeFindingSummaries: c.IncludeFindingSummaries,
			UploadSarif:             c.UploadSARIF,
		}
	}
	for _, rule := range spec.Notifications {
		pbRule := &platform.SecurityScanNotificationRuleConfig{
			Name:        rule.Name,
			MinSeverity: rule.MinSeverity,
			NotifyOn:    rule.NotifyOn,
		}
		if rule.Slack != nil {
			pbRule.SlackWebhookSecretRef = rule.Slack.WebhookSecretRef
		}
		if rule.GitHubIssues != nil {
			pbRule.GithubIssues = true
			if rule.GitHubIssues.RepositoryRef != nil {
				pbRule.GithubRepositoryRef = rule.GitHubIssues.RepositoryRef.Name
			}
		}
		if rule.Linear != nil {
			pbRule.LinearApiKeySecretRef = rule.Linear.APIKeySecretRef
			pbRule.LinearTeamId = rule.Linear.TeamID
		}
		pb.Notifications = append(pb.Notifications, pbRule)
	}
	return pb
}

func securityScanExecutionFromProto(pb *platform.SecurityScanExecutionConfig) (*triggersv1alpha1.SecurityScanExecution, error) {
	if pb == nil {
		return nil, nil
	}
	invalid := func(format string, args ...any) error {
		return connect.NewError(connect.CodeInvalidArgument, fmt.Errorf(format, args...))
	}
	exec := &triggersv1alpha1.SecurityScanExecution{}
	switch mode := strings.TrimSpace(pb.GetMode()); mode {
	case "", triggersv1alpha1.SecurityScanExecutionModeCoordinator, triggersv1alpha1.SecurityScanExecutionModeDeterministic:
		exec.Mode = mode
	default:
		return nil, invalid("invalid execution.mode %q (want coordinator or deterministic)", pb.GetMode())
	}
	if pb.TaskMaxRetries != nil {
		retries := pb.GetTaskMaxRetries()
		if retries < 0 || retries > 10 {
			return nil, invalid("execution.task_max_retries %d out of range (want 0-10)", retries)
		}
		exec.TaskMaxRetries = &retries
	}
	if value := strings.TrimSpace(pb.GetRetryBackoff()); value != "" {
		d, err := time.ParseDuration(value)
		if err != nil {
			return nil, invalid("invalid execution.retry_backoff %q: %v", value, err)
		}
		if d < 0 {
			return nil, invalid("execution.retry_backoff must not be negative")
		}
		exec.RetryBackoff = metav1.Duration{Duration: d}
	}
	if pb.MaxEnvRetries != nil {
		retries := pb.GetMaxEnvRetries()
		if retries < 0 || retries > 10 {
			return nil, invalid("execution.max_env_retries %d out of range (want 0-10)", retries)
		}
		exec.MaxEnvRetries = &retries
	}
	if exec.Mode == "" && exec.TaskMaxRetries == nil && exec.RetryBackoff.Duration == 0 && exec.MaxEnvRetries == nil {
		return nil, nil
	}
	return exec, nil
}

func TestRunSecurityScanNowMergesParameterValues(t *testing.T) {
	ns := testUserNS()
	existing := &triggersv1alpha1.SecurityScan{
		ObjectMeta: metav1.ObjectMeta{Name: "parameterized", Namespace: ns},
		Spec: triggersv1alpha1.SecurityScanSpec{
			RepoURL:         "https://github.com/example/app.git",
			ParameterValues: map[string]string{"target_env": "prod", "depth": "quick"},
		},
	}
	srv, c := newCronTestServer(t, existing)
	ms := newMockStateStore()
	srv.stateStore = ms
	if err := ms.SetResourceOwner(context.Background(), securityScanResourceType, "parameterized", ns, testProjectSubject); err != nil {
		t.Fatalf("SetResourceOwner: %v", err)
	}

	resp, err := srv.RunSecurityScanNow(projectActorCtx(), &platform.RunSecurityScanNowRequest{
		Namespace: ns, Name: "parameterized",
		ParameterValues: map[string]string{"target_env": "staging", "focus": "auth"},
	})
	if err != nil {
		t.Fatalf("RunSecurityScanNow() error = %v", err)
	}
	if resp.GetSpec().GetParameterValues()["target_env"] != "staging" {
		t.Fatalf("resp parameter values = %+v", resp.GetSpec().GetParameterValues())
	}

	cr := &triggersv1alpha1.SecurityScan{}
	if err := c.Get(context.Background(), client.ObjectKey{Namespace: ns, Name: "parameterized"}, cr); err != nil {
		t.Fatalf("Get(SecurityScan) error = %v", err)
	}
	want := map[string]string{"target_env": "staging", "depth": "quick", "focus": "auth"}
	if len(cr.Spec.ParameterValues) != len(want) {
		t.Fatalf("ParameterValues = %+v, want %+v", cr.Spec.ParameterValues, want)
	}
	for k, v := range want {
		if cr.Spec.ParameterValues[k] != v {
			t.Fatalf("ParameterValues[%q] = %q, want %q", k, cr.Spec.ParameterValues[k], v)
		}
	}
	if cr.Annotations[triggersv1alpha1.SecurityScanRunNowAnnotation] == "" {
		t.Fatalf("run-now annotation missing: %#v", cr.Annotations)
	}

	// Invalid parameter names are rejected before anything is stamped.
	_, err = srv.RunSecurityScanNow(projectActorCtx(), &platform.RunSecurityScanNowRequest{
		Namespace: ns, Name: "parameterized",
		ParameterValues: map[string]string{"not a name": "x"},
	})
	if connect.CodeOf(err) != connect.CodeInvalidArgument {
		t.Fatalf("RunSecurityScanNow(bad key) error = %v, want InvalidArgument", err)
	}
}

