func TestUpstreamRevisionMustBeTheExactPinnedCommit(t *testing.T) {
	mirror, repository := t.TempDir(), t.TempDir()
	gitOrSkip(t, mirror, "init", "--quiet", "--initial-branch", "main")
	gitOrSkip(t, mirror, "config", "user.email", "operator@example.test")
	gitOrSkip(t, mirror, "config", "user.name", "operator")
	if err := os.WriteFile(filepath.Join(mirror, "evm.go"), []byte("package vm\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	gitOrSkip(t, mirror, "add", "evm.go")
	gitOrSkip(t, mirror, "commit", "--quiet", "-m", "upstream")
	revision := gitOrSkip(t, mirror, "rev-parse", "HEAD")
	gitOrSkip(t, repository, "init", "--quiet", "--initial-branch", "main")

	t.Setenv(operatorConfigurationName(evmUpstreamMirrorEnvPrefix, "go-ethereum"), mirror)
	resolved, err := materializeUpstreamRevision(t.Context(), "go-ethereum@"+revision, repository)
	if err != nil || resolved != revision {
		t.Fatalf("pinned upstream revision resolved to %q (%v)", resolved, err)
	}
	if got := gitOrSkip(t, repository, "cat-file", "-t", revision); got != "commit" {
		t.Fatalf("mirror fetch did not materialize the commit locally: %q", got)
	}

	// A revision the mirror cannot produce must fail closed, never diff against
	// whatever ref happened to be fetched.
	for name, reference := range map[string]string{
		"revision mismatch":  "go-ethereum@" + strings.Repeat("ab", 20),
		"unreviewed name":    "attacker-fork@" + revision,
		"unpinned revision":  "go-ethereum@main",
		"missing separator":  "go-ethereum",
		"unconfigured chain": "reth@" + revision,
	} {
		if _, err := materializeUpstreamRevision(t.Context(), reference, repository); err == nil {
			t.Errorf("%s (%q) was accepted", name, reference)
		}
	}
	t.Setenv(operatorConfigurationName(evmUpstreamMirrorEnvPrefix, "go-ethereum"), "http://mirror.example.test/geth.git")
	if _, err := materializeUpstreamRevision(t.Context(), "go-ethereum@"+revision, repository); err == nil {
		t.Error("a plaintext mirror URL was accepted")
	}
}

const (
	operatorForkEndpointToken = "@operator/evm-fork-endpoint/"
	operatorUpstreamToken     = "@operator/evm-upstream/"

	// evmForkEndpointsEnv is set by the operator (never by a model or a scan
	// request) to the comma-separated aliases a fork pack may use.
	evmForkEndpointsEnv = "GA_SECURITY_EVM_FORK_ENDPOINTS"
)

func evmForkEndpointAliases() []string {
	aliases := []string{}
	for entry := range strings.SplitSeq(os.Getenv(evmForkEndpointsEnv), ",") {
		alias := strings.TrimSpace(entry)
		if evmForkEndpointAliasPattern.MatchString(alias) && !slices.Contains(aliases, alias) {
			aliases = append(aliases, alias)
		}
	}
	slices.Sort(aliases)
	return aliases
}

func evmForkPinningArguments() []Argument {
	return []Argument{
		{Name: "fork_endpoint", Type: "enum", Required: true, Enum: evmForkEndpointAliases()},
		{Name: "chain_id", Type: "integer", Required: true},
		{Name: "fork_block_number", Type: "integer", Required: true},
		{Name: "fork_block_hash", Type: "evm_block_hash", Required: true},
	}
}

func TestEVMForkPacksRequirePinnedChainState(t *testing.T) {
	t.Setenv(evmForkEndpointsEnv, "mainnet-archive,base-archive")
	wantTypes := map[string]string{
		"fork_endpoint":     "enum",
		"chain_id":          "integer",
		"fork_block_number": "integer",
		"fork_block_hash":   "evm_block_hash",
	}
	for _, name := range evmForkPacks {
		tool := evmPack(t, name)
		seen := map[string]Argument{}
		for _, argument := range tool.Arguments {
			seen[argument.Name] = argument
		}
		for argumentName, argumentType := range wantTypes {
			argument, ok := seen[argumentName]
			if !ok {
				t.Fatalf("%s is missing pinning argument %q", name, argumentName)
			}
			if !argument.Required {
				t.Errorf("%s argument %q must be required", name, argumentName)
			}
			if argument.Type != argumentType {
				t.Errorf("%s argument %q type = %q, want %q", name, argumentName, argument.Type, argumentType)
			}
		}
		if !slices.Equal(seen["fork_endpoint"].Enum, []string{"base-archive", "mainnet-archive"}) {
			t.Errorf("%s fork endpoint enum = %v, want the operator-authorized aliases", name, seen["fork_endpoint"].Enum)
		}
		argv := strings.Join(tool.Invocation, " ")
		for _, token := range []string{operatorForkEndpointToken + "{{fork_endpoint}}", "{{fork_block_number}}", "{{chain_id}}"} {
			if !strings.Contains(argv, token) {
				t.Errorf("%s argv %q does not carry %q", name, argv, token)
			}
		}
	}
}

