func TestForkInvocationResolvesOnlyOperatorEndpointAliases(t *testing.T) {
	t.Setenv(evmForkEndpointsEnv, "mainnet-archive")
	registry := evmTestRegistry(t, "forge-fork-test")
	seed := int64(11)
	valid := map[string]string{
		"fork_endpoint":     "mainnet-archive",
		"chain_id":          "1",
		"fork_block_number": "21000000",
		"fork_block_hash":   "0x" + strings.Repeat("ab", 32),
	}
	invocation, _, err := registry.BuildInvocation(forkRunConfig(valid, &seed))
	if err != nil {
		t.Fatalf("pinned fork request: %v", err)
	}
	if !slices.Contains(invocation.Argv, operatorForkEndpointToken+"mainnet-archive") {
		t.Fatalf("argv %v does not carry the operator endpoint alias", invocation.Argv)
	}
	for _, token := range invocation.Argv {
		if strings.Contains(token, "://") {
			t.Fatalf("argv token %q carries a URL", token)
		}
	}
	if !slices.Contains(invocation.Argv, "21000000") || !slices.Contains(invocation.Argv, "1") {
		t.Fatalf("argv %v does not pin the forked chain state", invocation.Argv)
	}

	rejected := map[string]map[string]string{
		"model-supplied endpoint URL": {"fork_endpoint": "https://mainnet.example.test"},
		"unpinned chain id":           {"chain_id": ""},
		"zero chain id":               {"chain_id": "0"},
		"negative block":              {"fork_block_number": "-1"},
		"short block hash":            {"fork_block_hash": "0xdeadbeef"},
		"uppercase block hash":        {"fork_block_hash": "0x" + strings.Repeat("AB", 32)},
	}
	for name, override := range rejected {
		arguments := maps.Clone(valid)
		for key, value := range override {
			if value == "" {
				delete(arguments, key)
				continue
			}
			arguments[key] = value
		}
		if _, _, err := registry.BuildInvocation(forkRunConfig(arguments, &seed)); err == nil {
			t.Errorf("%s was accepted", name)
		}
	}
	if _, _, err := registry.BuildInvocation(forkRunConfig(valid, nil)); err == nil {
		t.Error("fork test without an explicit seed was accepted")
	}
}

func TestEVMPackArgumentsRejectFreeFormCommandsAndURLs(t *testing.T) {
	t.Setenv(evmForkEndpointsEnv, "mainnet-archive")
	allowed := []string{"enum", "integer", "evm_block_hash", "git_revision", "string"}
	for _, name := range evmPackNames {
		tool := evmPack(t, name)
		for _, argument := range tool.Arguments {
			if !slices.Contains(allowed, argument.Type) {
				t.Errorf("%s argument %q has free-form type %q", name, argument.Name, argument.Type)
			}
			// Only the fork endpoint enum may be empty: its values come from
			// operator configuration rather than from the compiled catalog.
			if argument.Type == "enum" && len(argument.Enum) == 0 && argument.Name != "fork_endpoint" {
				t.Errorf("%s enum argument %q has no reviewed values", name, argument.Name)
			}
		}
		for _, token := range tool.Invocation {
			if strings.Contains(token, "://") {
				t.Errorf("%s argv token %q embeds a URL", name, token)
			}
			if strings.HasPrefix(token, "@") && !strings.HasPrefix(token, operatorForkEndpointToken) && !strings.HasPrefix(token, operatorUpstreamToken) {
				t.Errorf("%s argv token %q is not an operator-resolved reference", name, token)
			}
		}
	}

	registry := evmTestRegistry(t, "medusa", "upstream-fork-diff")
	medusaTarget := Target{Type: "solidity_project", Locator: "project", Revision: "v1", Digest: sha256Digest([]byte("target")), MediaType: "application/vnd.gratefulagents.solidity-project.v1+directory"}
	for _, value := range []string{"https://example.test/x", "Vault; rm -rf /", "../../etc/passwd", "Vault --config /etc/shadow"} {
		cfg := RunConfig{Tool: "medusa", Target: medusaTarget, Arguments: map[string]string{"target_contracts": value}}
		if _, _, err := registry.BuildInvocation(cfg); err == nil {
			t.Errorf("medusa accepted free-form target_contracts %q", value)
		}
	}
	valid := RunConfig{Tool: "medusa", Target: medusaTarget, Arguments: map[string]string{"target_contracts": "VaultHarness,TokenHarness"}}
	if _, _, err := registry.BuildInvocation(valid); err != nil {
		t.Fatalf("valid medusa contract list: %v", err)
	}

	gitTarget := Target{Type: "git_repository", Locator: "repo", Revision: "v1", Digest: sha256Digest([]byte("target")), MediaType: "application/vnd.gratefulagents.git-repository.v1+directory"}
	revision := strings.Repeat("a1b2c3d4", 5)
	invocation, _, err := registry.BuildInvocation(RunConfig{Tool: "upstream-fork-diff", Target: gitTarget, Arguments: map[string]string{"upstream": "go-ethereum", "upstream_revision": revision}})
	if err != nil {
		t.Fatalf("valid upstream diff: %v", err)
	}
	if !slices.Contains(invocation.Argv, operatorUpstreamToken+"go-ethereum@"+revision) {
		t.Fatalf("argv %v does not pin the reviewed upstream revision", invocation.Argv)
	}
	for _, arguments := range []map[string]string{
		{"upstream": "https://github.com/attacker/geth", "upstream_revision": revision},
		{"upstream": "go-ethereum", "upstream_revision": "main"},
		{"upstream": "go-ethereum", "upstream_revision": strings.ToUpper(revision)},
		{"upstream": "go-ethereum"},
	} {
		if _, _, err := registry.BuildInvocation(RunConfig{Tool: "upstream-fork-diff", Target: gitTarget, Arguments: arguments}); err == nil {
			t.Errorf("upstream diff accepted %v", arguments)
		}
	}
}

func resolveForkEndpoint(alias string) (string, error) {
	if !slices.Contains(evmForkEndpointAliases(), alias) {
		return "", fmt.Errorf("fork endpoint alias %q is not authorized by %s", alias, evmForkEndpointsEnv)
	}
	variable := operatorConfigurationName(evmForkEndpointURLEnvPrefix, alias)
	endpoint := strings.TrimSpace(os.Getenv(variable))
	if endpoint == "" {
		return "", fmt.Errorf("fork endpoint alias %q has no operator-configured URL in %s", alias, variable)
	}
	parsed, err := url.Parse(endpoint)
	if err != nil || !parsed.IsAbs() || (parsed.Scheme != "http" && parsed.Scheme != "https") || parsed.Host == "" || parsed.Fragment != "" {
		return "", fmt.Errorf("%s must hold an absolute http(s) fork endpoint URL", variable)
	}
	return endpoint, nil
}

func resolveOperatorEVMTokens(ctx context.Context, argv []string, repository string, secrets *operatorSecret) error {
	for i := range argv {
		if alias, ok := strings.CutPrefix(argv[i], operatorForkEndpointToken); ok {
			endpoint, err := resolveForkEndpoint(alias)
			if err != nil {
				return err
			}
			secrets.hide(endpoint, operatorForkEndpointToken+alias)
			argv[i] = endpoint
			continue
		}
		if reference, ok := strings.CutPrefix(argv[i], operatorUpstreamToken); ok {
			revision, err := materializeUpstreamRevision(ctx, reference, repository)
			if err != nil {
				return err
			}
			argv[i] = revision
		}
	}
	return nil
}

func executeEVMStage(ctx context.Context, req ExecutionRequest, argv []string, executionTarget string, childEnvironment []string, secrets *operatorSecret) (NativeResult, bool) {
	environment := map[string]string{"os": runtime.GOOS, "arch": runtime.GOARCH, "runtime": runtime.Version()}
	switch req.Tool.Name {
	case "anvil-fork":
		output, err := runForkDevnet(ctx, req, argv, childEnvironment, secrets)
		return evmStageResult(ctx, environment, output, 0, err), true
	case "forge-fork-test":
		if err := verifyForgeForkPin(ctx, req.Config.Arguments, argv, secrets); err != nil {
			return evmStageResult(ctx, environment, nil, 0, err), true
		}
	case "forge-coverage-mutation":
		limit := req.Invocation.Budgets.MaxOutputSize
		run := func(runCtx context.Context, root string) (int, []byte, error) {
			mutantArgv := slices.Clone(argv)
			for i := range mutantArgv {
				if mutantArgv[i] == executionTarget {
					mutantArgv[i] = root
				}
			}
			suite := exec.CommandContext(runCtx, mutantArgv[0], mutantArgv[1:]...) // #nosec G204 -- registry argv with only the staged root swapped for its mutant copy.
			suite.Env = childEnvironment
			output := &limitedBuffer{limit: limit}
			suite.Stdout, suite.Stderr = output, io.Discard
			err := suite.Run()
			if processExitCode(err) < 0 {
				return -1, nil, err
			}
			return processExitCode(err), output.Bytes(), nil
		}
		output, survivors, err := runMutationCampaign(ctx, executionTarget, req.Config.Arguments["mutation_operator"], run)
		exitCode := 0
		if survivors > 0 {
			exitCode = 1
		}
		return evmStageResult(ctx, environment, output, exitCode, err), true
	case "chain-read", "deployed-bytecode-diff":
		output, err := runChainStatePack(ctx, req, argv, executionTarget)
		return evmStageResult(ctx, environment, output, 0, err), true
	}
	return NativeResult{}, false
}

func ResolveEVMForkPin(ctx context.Context, alias string, expectedChainID int64) (pin EVMForkPin, err error) {
	if expectedChainID < 1 {
		return EVMForkPin{}, fmt.Errorf("expected chain id must be positive")
	}
	endpoint, err := resolveForkEndpoint(alias)
	if err != nil {
		return EVMForkPin{}, err
	}
	secrets := &operatorSecret{}
	secrets.hide(endpoint, operatorForkEndpointToken+alias)
	defer func() { err = secrets.err(err) }()

	client := &http.Client{Timeout: 20 * time.Second, Transport: &http.Transport{Proxy: nil, DisableKeepAlives: true}}
	var quantity string
	if err := jsonRPCCall(ctx, client, endpoint, "fork endpoint", "eth_chainId", []any{}, &quantity); err != nil {
		return EVMForkPin{}, err
	}
	chainID, err := parseHexQuantity(quantity)
	if err != nil {
		return EVMForkPin{}, err
	}
	if chainID != expectedChainID {
		return EVMForkPin{}, fmt.Errorf("fork endpoint serves chain id %d, expected %d", chainID, expectedChainID)
	}
	var block struct {
		Number string `json:"number"`
		Hash   string `json:"hash"`
	}
	if err := jsonRPCCall(ctx, client, endpoint, "fork endpoint", "eth_getBlockByNumber", []any{"finalized", false}, &block); err != nil {
		return EVMForkPin{}, err
	}
	blockNumber, err := parseHexQuantity(block.Number)
	if err != nil {
		return EVMForkPin{}, err
	}
	blockHash := strings.ToLower(block.Hash)
	if !evmBlockHashPattern.MatchString(blockHash) {
		return EVMForkPin{}, fmt.Errorf("fork endpoint returned a malformed finalized block hash")
	}
	return EVMForkPin{ChainID: chainID, ForkBlockNumber: blockNumber, ForkBlockHash: blockHash}, nil
}

func verifyForgeForkPin(ctx context.Context, arguments map[string]string, argv []string, secrets *operatorSecret) error {
	pin, err := forkPinFromArguments(arguments)
	if err != nil {
		return err
	}
	configuredEndpoint, err := resolveForkEndpoint(arguments["fork_endpoint"])
	if err != nil {
		return err
	}
	secrets.hide(configuredEndpoint, operatorForkEndpointToken+arguments["fork_endpoint"])
	endpoint := ""
	for i := 0; i+1 < len(argv); i++ {
		if argv[i] == "--fork-url" {
			if endpoint != "" {
				return fmt.Errorf("forge fork test has multiple fork endpoints")
			}
			endpoint = argv[i+1]
		}
	}
	if endpoint == "" || endpoint != configuredEndpoint {
		return fmt.Errorf("forge fork test has no resolved operator endpoint")
	}
	client := &http.Client{Timeout: 20 * time.Second, Transport: &http.Transport{Proxy: nil, DisableKeepAlives: true}}
	reader := chainReader{client: client, endpoint: endpoint, block: "0x" + strconv.FormatInt(pin.ForkBlockNumber, 16)}
	if err := reader.verifyPin(ctx, pin.ChainID, pin.ForkBlockNumber, pin.ForkBlockHash); err != nil {
		return secrets.err(fmt.Errorf("forge fork preflight: %w", err))
	}
	return nil
}

func evmStageResult(ctx context.Context, environment map[string]string, output []byte, exitCode int, err error) NativeResult {
	if ctx.Err() == context.DeadlineExceeded {
		return NativeResult{Environment: environment, ExitCode: 124, TimedOut: true, Err: context.DeadlineExceeded}
	}
	if err != nil {
		return NativeResult{Environment: environment, ExitCode: 2, Err: err}
	}
	return NativeResult{Output: output, Environment: environment, ExitCode: exitCode}
}

func runForkDevnet(ctx context.Context, req ExecutionRequest, argv, childEnvironment []string, secrets *operatorSecret) ([]byte, error) {
	pin, err := forkPinFromArguments(req.Config.Arguments)
	if err != nil {
		return nil, err
	}
	devnetArgv, listenURL, err := loopbackDevnetArgv(argv)
	if err != nil {
		return nil, err
	}
	return superviseForkDevnet(ctx, forkDevnetRequest{
		Argv: devnetArgv, Environment: childEnvironment, Alias: req.Config.Arguments["fork_endpoint"],
		ChainID: pin.ChainID, BlockNumber: pin.ForkBlockNumber, BlockHash: pin.ForkBlockHash, ListenURL: listenURL,
		Readiness: min(req.Invocation.Budgets.Timeout/2, forkDevnetReadinessCap),
		MaxLog:    min(req.Invocation.Budgets.MaxOutputSize, 1<<20), Secrets: secrets,
	})
}

func superviseForkDevnet(ctx context.Context, request forkDevnetRequest) ([]byte, error) {
	if !isLoopbackDevnet(request.ListenURL) {
		return nil, fmt.Errorf("fork devnet listen URL %q is not loopback", request.ListenURL)
	}
	log := &limitedBuffer{limit: max(request.MaxLog, 4096)}
	devnet := exec.CommandContext(ctx, request.Argv[0], request.Argv[1:]...) // #nosec G204 -- registry argv whose only resolved value is the operator fork endpoint.
	devnet.Env = request.Environment
	devnet.Stdout, devnet.Stderr = log, log
	// A devnet that leaves a child holding its output pipe must not hold the
	// supervisor open past its shutdown grace.
	devnet.WaitDelay = forkDevnetShutdown
	if err := devnet.Start(); err != nil {
		return nil, err
	}
	var waitErr error
	done := make(chan struct{})
	go func() { waitErr = devnet.Wait(); close(done) }()
	defer terminateForkDevnet(devnet, done)

	client := &http.Client{Timeout: 5 * time.Second, Transport: &http.Transport{Proxy: nil, DisableKeepAlives: true}}
	deadline := time.Now().Add(request.Readiness)
	var chainID int64
	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-done:
			return nil, fmt.Errorf("fork devnet exited before it was ready (%v): %s", waitErr, request.Secrets.text(strings.TrimSpace(log.String())))
		default:
		}
		id, err := devnetChainID(ctx, client, request.ListenURL)
		if err == nil {
			chainID = id
			break
		}
		if !time.Now().Before(deadline) {
			return nil, fmt.Errorf("fork devnet was not ready on %s within %s: %s", request.ListenURL, request.Readiness, request.Secrets.text(strings.TrimSpace(log.String())))
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-done:
		case <-time.After(forkDevnetPoll):
		}
	}
	if chainID != request.ChainID {
		return nil, fmt.Errorf("fork devnet reported chain id %d, but the run pinned %d", chainID, request.ChainID)
	}
	number, hash, err := devnetForkBlock(ctx, client, request.ListenURL)
	if err != nil {
		return nil, err
	}
	if number != request.BlockNumber || hash != request.BlockHash {
		return nil, fmt.Errorf("fork devnet head is block %d (%s), but the run pinned block %d (%s)", number, hash, request.BlockNumber, request.BlockHash)
	}
	return json.Marshal(evmForkRecord{ChainID: chainID, ForkBlockNumber: number, ForkBlockHash: hash, EndpointAlias: request.Alias, ListenURL: request.ListenURL})
}

func jsonRPCCall(ctx context.Context, client *http.Client, endpoint, label, method string, params []any, out any) error {
	body, err := json.Marshal(map[string]any{"jsonrpc": "2.0", "id": 1, "method": method, "params": params})
	if err != nil {
		return err
	}
	request, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return err
	}
	request.Header.Set("Content-Type", "application/json")
	response, err := client.Do(request)
	if err != nil {
		return err
	}
	defer func() { _ = response.Body.Close() }()
	payload, err := io.ReadAll(io.LimitReader(response.Body, 1<<20))
	if err != nil {
		return err
	}
	var envelope struct {
		Result json.RawMessage `json:"result"`
		Error  *struct {
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(payload, &envelope); err != nil {
		return fmt.Errorf("%s %s response is not JSON-RPC: %w", label, method, err)
	}
	if envelope.Error != nil {
		return nodeRejection{label: label, method: method, message: envelope.Error.Message}
	}
	if len(envelope.Result) == 0 || string(envelope.Result) == "null" {
		return nodeRejection{label: label, method: method, message: "returned no result"}
	}
	return json.Unmarshal(envelope.Result, out)
}

func materializeUpstreamRevision(ctx context.Context, reference, repository string) (string, error) {
	name, revision, found := strings.Cut(reference, "@")
	if !found || !slices.Contains(evmUpstreams, name) {
		return "", fmt.Errorf("upstream reference %q does not name a reviewed upstream", reference)
	}
	if !gitRevisionPattern.MatchString(revision) {
		return "", fmt.Errorf("upstream %s must be pinned to a full 40-hex commit id", name)
	}
	variable := operatorConfigurationName(evmUpstreamMirrorEnvPrefix, name)
	mirror := strings.TrimSpace(os.Getenv(variable))
	if mirror == "" {
		return "", fmt.Errorf("upstream %s has no operator-configured mirror in %s", name, variable)
	}
	if !isOperatorMirror(mirror) {
		return "", fmt.Errorf("%s must be an https URL or an absolute directory path", variable)
	}
	git, err := exec.LookPath("git")
	if err != nil {
		return "", fmt.Errorf("git is unavailable in the runtime image: %w", err)
	}
	for _, arguments := range [][]string{
		{"fetch", "--no-tags", "--quiet", mirror, revision},
		{"fetch", "--no-tags", "--quiet", mirror, "+refs/heads/*:refs/ga-upstream/" + name + "/*"},
	} {
		if _, fetchErr := runGit(ctx, git, repository, arguments...); fetchErr == nil {
			break
		}
	}
	resolved, err := runGit(ctx, git, repository, "rev-parse", "--verify", "--quiet", revision+"^{commit}")
	if err != nil || resolved != revision {
		return "", fmt.Errorf("upstream %s mirror did not provide the pinned commit %s", name, revision)
	}
	return revision, nil
}

func runGit(ctx context.Context, git, repository string, arguments ...string) (string, error) {
	command := exec.CommandContext(ctx, git, append([]string{"-C", repository}, arguments...)...) // #nosec G204 -- git from LookPath, operator-configured mirror, and a validated 40-hex revision.
	output := &limitedBuffer{limit: 1 << 20}
	command.Stdout, command.Stderr = output, io.Discard
	command.Env = []string{"HOME=" + os.TempDir(), "LANG=C.UTF-8", "GIT_TERMINAL_PROMPT=0", "GIT_CONFIG_NOSYSTEM=1", "GIT_ASKPASS=", "PATH=" + os.Getenv("PATH")}
	err := command.Run()
	return strings.TrimSpace(output.String()), err
}

func (ProcessSandbox) Execute(ctx context.Context, req ExecutionRequest) (result NativeResult) {
	// Operator-configured fork endpoints carry API keys. Nothing this executor
	// returns may echo one, so every exit path is scrubbed.
	secrets := &operatorSecret{}
	defer func() { result = secrets.scrub(result) }()
	if len(req.Invocation.Argv) == 0 {
		return NativeResult{ExitCode: -1, Err: errors.New("empty registered invocation")}
	}
	if result, ok := executeBuiltin(req); ok {
		return result
	}
	if err := verifyFileTarget(req.Config.Target); err != nil {
		return NativeResult{ExitCode: -1, Err: err}
	}
	ctx, cancel := context.WithTimeout(ctx, req.Invocation.Budgets.Timeout)
	defer cancel()

	limit := req.Invocation.Budgets.MaxOutputSize
	stdout := &limitedBuffer{limit: limit}
	stderr := &limitedBuffer{limit: min(limit, 1<<20)}
	argv := slices.Clone(req.Invocation.Argv)
	executionTarget := req.Config.Target.Locator
	if snapshot, cleanup, err := snapshotDirectoryTarget(req.Config.Target); err != nil {
		return NativeResult{ExitCode: -1, Err: err}
	} else if snapshot != "" {
		defer cleanup()
		executionTarget = snapshot
		for i := range argv {
			if argv[i] == req.Config.Target.Locator {
				argv[i] = snapshot
			}
		}
	}
	if req.Tool.Name == "owasp-zap" {
		if err := validateZAPPlan(executionTarget, req.Config.Arguments["base_url"], req.Config.Scope); err != nil {
			return NativeResult{ExitCode: -1, Err: err}
		}
	}
	if req.Tool.Name == "schemathesis" {
		if err := validateOpenAPIBudget(executionTarget, 100); err != nil {
			return NativeResult{ExitCode: -1, Err: err}
		}
	}
	if req.Tool.Name == "slither" && runtime.GOARCH == "arm64" {
		return NativeResult{ExitCode: -1, Err: fmt.Errorf("slither project compilation is unsupported on arm64: the pinned upstream toolbox embeds an amd64 solc artifact")}
	}
	ociWork := ""
	if req.Tool.OCIRoot != "" {
		prepared, work, cleanup, err := prepareOCIInvocation(req.Tool, argv, executionTarget)
		if err != nil {
			return NativeResult{ExitCode: -1, Err: err}
		}
		defer cleanup()
		argv, ociWork = prepared, work
	}
	if isLockedExternalTool(req.Tool.Name) {
		binary, err := trustedToolBinary(argv[0], req.Tool.ToolArtifactDigest)
		if err != nil {
			return NativeResult{ExitCode: -1, Err: err}
		}
		argv[0] = binary
	}
	if req.Tool.Name == "nuclei" {
		knowledge, err := trustedNucleiKnowledge(req.Tool.KnowledgeDigests["bundle"])
		if err != nil {
			return NativeResult{ExitCode: -1, Err: err}
		}
		for i := range argv {
			if argv[i] == "@operator/nuclei-reviewed.yaml" {
				argv[i] = knowledge
			}
		}
	}
	if err := resolveOperatorEVMTokens(ctx, argv, executionTarget, secrets); err != nil {
		return NativeResult{ExitCode: -1, Err: err}
	}
	home, homeErr := os.MkdirTemp("", "ga-security-home-*")
	if homeErr != nil {
		return NativeResult{ExitCode: -1, Err: homeErr}
	}
	defer func() { _ = os.RemoveAll(home) }()
	childEnvironment := deterministicEnvironment(req.Tool.Name, home)
	if staged, handled := executeEVMStage(ctx, req, argv, executionTarget, childEnvironment, secrets); handled {
		return staged
	}
	cmd := exec.CommandContext(ctx, argv[0], argv[1:]...) // #nosec G204 -- executable and argv come only from the validated static registry.
	cmd.Env = childEnvironment
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	goFuzzBaseline := map[string]bool{}
	goFuzzTargetBaseline := map[string]bool{}
	goFuzzPackage, goFuzzTarget, goFuzzSeeds, goFuzzRestored := "", "", 0, 0
	rustCrashBaseline := map[string]bool{}
	rustCorpusBaseline := map[string]bool{}
	rustCorpusInputs, rustCorpusRestored := 0, 0
	rustHarnessDigest, rustManifestDigest, rustHarnessRelative := "", "", ""
	if req.Tool.Name == "cargo-fuzz" {
		existing, baselineErr := rustFuzzCrashPaths(executionTarget, req.Config.Arguments["fuzz_target"])
		if baselineErr != nil {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("inventory cargo-fuzz artifacts: %w", baselineErr)}
		}
		for _, path := range existing {
			rustCrashBaseline[path] = true
		}
		rustCorpusRestored, baselineErr = readRustFuzzCampaignMetadata(executionTarget)
		if baselineErr != nil {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("read Rust fuzz campaign provenance: %w", baselineErr)}
		}
		rustCorpusBaseline, baselineErr = rustFuzzCorpusPaths(executionTarget, req.Config.Arguments["fuzz_target"])
		if baselineErr != nil {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("inventory cargo-fuzz corpus: %w", baselineErr)}
		}
		rustCorpusInputs = len(rustCorpusBaseline)
		harnessPath, manifestPath, pathErr := rustFuzzHarnessPath(executionTarget, req.Config.Arguments["fuzz_target"])
		if pathErr != nil {
			return NativeResult{ExitCode: -1, Err: pathErr}
		}
		if relative, relErr := filepath.Rel(executionTarget, harnessPath); relErr == nil {
			rustHarnessRelative = filepath.ToSlash(relative)
		} else {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("resolve Rust fuzz harness path: %w", relErr)}
		}
		if data, readErr := os.ReadFile(harnessPath); readErr == nil {
			rustHarnessDigest = sha256Digest(data)
		} else {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("hash Rust fuzz harness: %w", readErr)}
		}
		if data, readErr := os.ReadFile(manifestPath); readErr == nil {
			rustManifestDigest = sha256Digest(data)
		} else {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("hash Rust fuzz manifest: %w", readErr)}
		}
	}
	if req.Tool.Name == "go-fuzz-tests" {
		var baselineErr error
		goFuzzRestored, baselineErr = readGoFuzzCampaignMetadata(executionTarget)
		if baselineErr != nil {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("read Go fuzz campaign provenance: %w", baselineErr)}
		}
		goFuzzBaseline, baselineErr = goFuzzCorpusPaths(executionTarget)
		if baselineErr != nil {
			return NativeResult{ExitCode: -1, Err: fmt.Errorf("inventory Go fuzz corpus: %w", baselineErr)}
		}
		goFuzzPackage = GoFuzzPackageDir(executionTarget, req.Config.Arguments["package"])
		goFuzzTarget = GoFuzzTargetName(req.Config.Arguments["fuzz"])
		goFuzzTargetBaseline = seedCorpusPaths(goFuzzPackage, goFuzzTarget)
		goFuzzSeeds = len(goFuzzTargetBaseline)
	}
	var err error
	executionStarted := time.Now()
	if ociWork != "" {
		quotaDirectories := []string{ociWork}
		quotaLimit, quotaEntries := limit, 4096
		if req.Tool.OCIWritableTarget {
			baselineBytes, baselineEntries, usageErr := directoryUsage(executionTarget)
			if usageErr != nil {
				return NativeResult{ExitCode: -1, Err: usageErr}
			}
			quotaLimit += baselineBytes
			quotaEntries += baselineEntries
			quotaDirectories = append(quotaDirectories, executionTarget)
		}
		err = runWithDirectoryLimits(cmd, quotaDirectories, quotaLimit, quotaEntries)
	} else {
		err = cmd.Run()
	}
	executionWallTime := time.Since(executionStarted)
	ociOutputCollected := req.Tool.OCIRoot == "" || req.Tool.OCIOutputPath == ""
	if req.Tool.OCIOutputPath != "" && ociWork != "" {
		if output, readErr := readBoundedOCIOutput(ociWork, filepath.Base(req.Tool.OCIOutputPath), limit); readErr == nil {
			if req.Tool.Name == "owasp-zap" && !zapReportExaminedTarget(output, req.Config.Arguments["base_url"], req.Config.Scope) {
				if err == nil {
					err = fmt.Errorf("ZAP report contains no examined site")
				}
			} else {
				ociOutputCollected = true
			}
			stdout.buf.Reset()
			_, _ = stdout.buf.Write(output)
		} else if errors.Is(readErr, errOutputTooLarge) {
			stdout.overflow = true
		} else if !os.IsNotExist(readErr) || slices.Contains([]string{"owasp-zap", "schemathesis"}, req.Tool.Name) {
			if err == nil {
				err = fmt.Errorf("collect OCI output: %w", readErr)
			}
		}
	}

	environment := map[string]string{"os": runtime.GOOS, "arch": runtime.GOARCH, "runtime": runtime.Version()}
	if req.Tool.OCIRoot != "" {
		sandboxPath := argv[0]
		if len(argv) > 4 && argv[1] == "__sandbox-exec" {
			sandboxPath = argv[4]
		}
		if data, readErr := os.ReadFile(sandboxPath); readErr == nil {
			environment["sandbox_digest"] = sha256Digest(data)
		} else if err == nil {
			err = fmt.Errorf("hash sandbox runtime: %w", readErr)
		}
		environment["scanner_platform_digest"] = req.Tool.PlatformDigests[runtime.GOARCH]
		environment["wrapper_digest"] = req.Tool.WrapperDigest
	}
	exitCode := processExitCode(err)
	result = NativeResult{Output: stdout.Bytes(), ExitCode: exitCode, Environment: environment}
	if req.Tool.Name == "go-fuzz-tests" {
		// Everything the campaign learned lives in the build cache and would
		// die with the sandbox. Promote a bounded sample into the package's
		// seed corpus first, so it leaves as artifacts and seeds the next
		// campaign; then collect, which also picks up minimized crashers.
		_, promoteErr := promoteGeneratedCorpus(ociWork, goFuzzPackage, goFuzzTarget)
		if promoteErr != nil && err == nil {
			err = fmt.Errorf("promote Go fuzz corpus: %w", promoteErr)
		}
		artifacts, collectErr := collectGoFuzzArtifacts(executionTarget, goFuzzBaseline, limit)
		if collectErr != nil && err == nil {
			err = fmt.Errorf("collect Go fuzz reproducer: %w", collectErr)
		} else {
			result.Artifacts = artifacts
		}
		after := seedCorpusPaths(goFuzzPackage, goFuzzTarget)
		campaign, _ := ParseFuzzCampaign(req.Config.Arguments["fuzztime"])
		result.Bounded = goFuzzBoundedScope(
			req.Config.Arguments["package"], goFuzzTarget, campaign, executionWallTime,
			goFuzzSeeds, goFuzzRestored, len(after), newSeedCorpusCount(after, goFuzzTargetBaseline),
		)
	}
	if req.Tool.Name == "cargo-fuzz" {
		// The verdict comes from what the campaign left on disk, not from
		// libFuzzer's console text: a crash file is a reproducible input, a
		// stderr banner is a string that changes between releases.
		report, artifacts, collectErr := collectRustFuzzRun(executionTarget, rustCrashBaseline, req.Config, exitCode, append(stdout.Bytes(), stderr.Bytes()...))
		report.WallTime = executionWallTime.Round(time.Millisecond).String()
		// These digests were captured before target code ran, so a harness that
		// rewrites its own source cannot forge the campaign identity.
		report.HarnessDigest = rustHarnessDigest
		report.ManifestDigest = rustManifestDigest
		corpusArtifacts, rustCorpusAfter, discovered, corpusErr := collectRustFuzzCorpus(executionTarget, req.Config.Arguments["fuzz_target"], rustCorpusBaseline)
		crashDigests := map[string]bool{}
		for _, crash := range report.Crashes {
			crashDigests[crash.Digest] = true
		}
		corpusArtifacts = slices.DeleteFunc(corpusArtifacts, func(artifact Artifact) bool { return crashDigests[artifact.Digest] })
		if remaining := max(0, maxRustTotalArtifacts-len(artifacts)); len(corpusArtifacts) > remaining {
			corpusArtifacts = corpusArtifacts[:remaining]
		}
		report.CorpusInputs = rustCorpusInputs
		report.CorpusRestored = rustCorpusRestored
		report.CorpusOutputs = len(rustCorpusAfter)
		report.CorpusNew = discovered
		report.CorpusRetained = len(corpusArtifacts)
		report.CorpusProvenance = "cold"
		if rustCorpusRestored > 0 {
			report.CorpusProvenance = "restored"
		}
		if corpusErr != nil && len(report.Crashes) > 0 {
			report.CorpusError = corpusErr.Error()
		} else if collectErr == nil {
			collectErr = corpusErr
		}
		artifacts = append(artifacts, corpusArtifacts...)
		document, marshalErr := json.Marshal(report)
		if collectErr == nil {
			collectErr = marshalErr
		}
		if collectErr != nil {
			// Evidence that could not be collected is not a clean campaign and
			// not a findings campaign: the exit code says what the fuzzer did,
			// but we cannot show it, so the run fails outright rather than
			// letting the generic handler suppress this under a pass verdict.
			result.Output = nil
			result.ExitCode = 2
			result.Err = fmt.Errorf("collect cargo-fuzz campaign evidence: %w", collectErr)
			return result
		}
		result.Output = document
		result.Artifacts = artifacts
		result.Bounded = rustFuzzBoundedScope(req.Config, rustHarnessRelative, executionWallTime, rustCorpusInputs, rustCorpusRestored, len(rustCorpusAfter), discovered)
		if len(report.Crashes) > 0 && exitCode == 0 {
			// libFuzzer can report a crash and still exit zero under some
			// runners; the artifact is the fact, so the status follows it.
			exitCode = 1
			result.ExitCode = 1
		}
	}
	completeEvidence := ociOutputCollected || (req.Tool.Name == "zeek" && exitCode == 0)
	if exitCode >= 0 && completeEvidence {
		result.Examined = []string{req.Config.Target.Locator}
	} else if req.Tool.OCIRoot != "" {
		result.Uncovered = []string{req.Config.Target.Locator}
	}
	if ctx.Err() == context.DeadlineExceeded {
		result.TimedOut = true
		result.Err = context.DeadlineExceeded
		return result
	}
	if stdout.overflow || stderr.overflow {
		result.Err = fmt.Errorf("tool output exceeded budget (stdout limit %d bytes)", limit)
		return result
	}
	if err != nil {
		mapped := req.Tool.ExitCodes[exitCode]
		if mapped != StatusPass && mapped != StatusFindings {
			message := stderr.String()
			if message == "" {
				message = err.Error()
			}
			result.Err = errors.New(message)
		}
	}
	return result
}

func deterministicEnvironment(toolName, home string) []string {
	environment := []string{"HOME=" + home, "LANG=C.UTF-8", "LC_ALL=C.UTF-8", "PATH=" + os.Getenv("PATH")}
	for _, name := range []string{"SSL_CERT_FILE", "SSL_CERT_DIR"} {
		if value := os.Getenv(name); value != "" {
			environment = append(environment, name+"="+value)
		}
	}
	if slices.Contains([]string{"forge-security-tests", "anvil-fork", "forge-fork-test", "forge-coverage-mutation"}, toolName) {
		environment = append(environment, "FOUNDRY_FFI=false")
	}
	sort.Strings(environment)
	return environment
}

func executeBuiltin(req ExecutionRequest) (NativeResult, bool) {
	switch req.Invocation.Argv[0] {
	case "authz-matrix", "wycheproof-runner", "vector-runner", "crypto-differential":
		data, err := os.ReadFile(req.Config.Target.Locator) // #nosec G304 -- registry-validated typed target, covered by replay digest.
		result := NativeResult{
			Output: data, ExitCode: 0, Examined: []string{req.Config.Target.Locator},
			Environment: map[string]string{"runtime": runtime.Version(), "os": runtime.GOOS, "arch": runtime.GOARCH},
		}
		if err != nil {
			result.ExitCode, result.Err = -1, err
		} else if actual := sha256Digest(data); actual != req.Config.Target.Digest {
			result.ExitCode, result.Err = -1, fmt.Errorf("target digest mismatch: got %s, want %s", actual, req.Config.Target.Digest)
		}
		return result, true
	default:
		return NativeResult{}, false
	}
}

func ExecSandboxWithLimits(args []string) error {
	if len(args) < 3 {
		return fmt.Errorf("sandbox launcher requires file limit, memory limit, and argv")
	}
	fileLimit, err := strconv.ParseUint(args[0], 10, 64)
	if err != nil || fileLimit == 0 {
		return fmt.Errorf("invalid sandbox file limit")
	}
	memoryLimit, err := strconv.ParseUint(args[1], 10, 64)
	if err != nil || memoryLimit == 0 {
		return fmt.Errorf("invalid sandbox memory limit")
	}
	for resource, limit := range map[int]uint64{unix.RLIMIT_FSIZE: fileLimit, unix.RLIMIT_AS: memoryLimit, unix.RLIMIT_CORE: 0} {
		if err := unix.Setrlimit(resource, &unix.Rlimit{Cur: limit, Max: limit}); err != nil {
			return err
		}
	}
	return unix.Exec(args[2], args[2:], os.Environ())
}

func TestProcessSandboxRejectsPATHShadowForLockedTools(t *testing.T) {
	directory := t.TempDir()
	marker := filepath.Join(directory, "executed")
	shadow := filepath.Join(directory, "naabu")
	if err := os.WriteFile(shadow, []byte("#!/bin/sh\ntouch "+marker+"\n"), 0o700); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", directory+":"+os.Getenv("PATH"))
	request := ExecutionRequest{
		Tool:       Tool{Name: "naabu", ToolArtifactDigest: sha256Digest([]byte("not-the-shadow"))},
		Invocation: Invocation{Argv: []string{"naabu", "-version"}, Budgets: Budgets{Timeout: time.Second, MaxOutputSize: 1024}},
		Config:     RunConfig{Target: Target{Locator: "192.0.2.1"}},
	}
	result := (ProcessSandbox{}).Execute(context.Background(), request)
	if result.Err == nil {
		t.Fatal("expected operator-toolkit lookup failure")
	}
	if _, err := os.Stat(marker); !os.IsNotExist(err) {
		t.Fatal("PATH-shadowed tool was executed")
	}
}

func validateZAPPlan(path, configuredBaseURL string, scopes []string) error {
	data, err := os.ReadFile(path) // #nosec G304 -- the immutable target path is supplied by the typed request.
	if err != nil {
		return fmt.Errorf("read ZAP plan: %w", err)
	}
	if len(data) > 2<<20 {
		return fmt.Errorf("ZAP plan exceeds 2 MiB limit")
	}
	var document yaml.Node
	if err := yaml.Unmarshal(data, &document); err != nil {
		return fmt.Errorf("parse ZAP plan: %w", err)
	}
	if err := validateYAMLStructure(&document); err != nil {
		return fmt.Errorf("ZAP plan structure: %w", err)
	}
	urlCount := 0
	var walk func(*yaml.Node) error
	walk = func(node *yaml.Node) error {
		if node.Kind == yaml.AliasNode {
			return fmt.Errorf("ZAP plan aliases are not allowed")
		}
		if node.Kind == yaml.ScalarNode && node.Tag == "!!str" {
			if strings.Contains(node.Value, "${") || strings.Contains(node.Value, "{{") {
				return fmt.Errorf("ZAP plan substitutions are not allowed")
			}
			if parsed, parseErr := url.ParseRequestURI(node.Value); parseErr == nil && parsed.IsAbs() {
				parsed.Scheme = strings.ToLower(parsed.Scheme)
				if parsed.Scheme != "http" && parsed.Scheme != "https" {
					return fmt.Errorf("ZAP plan URI scheme %q is not allowed", parsed.Scheme)
				}
				canonical := parsed.String()
				urlCount++
				if !scopeAllowsTarget(canonical, scopes) {
					return fmt.Errorf("ZAP plan URL %q is outside configured scope", node.Value)
				}
			}
		}
		for _, child := range node.Content {
			if err := walk(child); err != nil {
				return err
			}
		}
		return nil
	}
	if err := walk(&document); err != nil {
		return err
	}
	if urlCount == 0 || !scopeAllowsTarget(configuredBaseURL, scopes) {
		return fmt.Errorf("ZAP plan must contain an in-scope absolute URL")
	}
	root := &document
	if root.Kind == yaml.DocumentNode && len(root.Content) == 1 {
		root = root.Content[0]
	}
	if err := validateZAPEnvironment(root, configuredBaseURL); err != nil {
		return err
	}
	jobs := yamlMappingValue(root, "jobs")
	if jobs == nil || jobs.Kind != yaml.SequenceNode {
		return fmt.Errorf("ZAP plan must declare jobs")
	}
	allowed := map[string]bool{"passiveScan-wait": true, "spider": true, "spiderAjax": true, "openapi": true, "activeScan": true, "report": true}
	reportFound := false
	scanFound := false
	for _, job := range jobs.Content {
		jobType := yamlMappingValue(job, "type")
		if jobType == nil || !allowed[jobType.Value] {
			return fmt.Errorf("ZAP plan job type %q is not allowed", scalarValue(jobType))
		}
		if err := requireYAMLKeys(job, "type", "parameters", "enabled"); err != nil {
			return fmt.Errorf("ZAP %s job: %w", jobType.Value, err)
		}
		if enabled := yamlMappingValue(job, "enabled"); enabled != nil && !strings.EqualFold(enabled.Value, "true") {
			return fmt.Errorf("ZAP scan jobs cannot be disabled")
		}
		if err := validateZAPJobParameters(jobType.Value, yamlMappingValue(job, "parameters")); err != nil {
			return err
		}
		if slices.Contains([]string{"spider", "spiderAjax", "openapi", "activeScan"}, jobType.Value) {
			scanFound = true
		}
		if jobType.Value != "report" {
			continue
		}
		params := yamlMappingValue(job, "parameters")
		if scalarValue(yamlMappingValue(params, "template")) != "traditional-json" || scalarValue(yamlMappingValue(params, "reportDir")) != "/work" || scalarValue(yamlMappingValue(params, "reportFile")) != "zap-report" {
			return fmt.Errorf("ZAP report job must write traditional-json to /work/zap-report.json")
		}
		reportFound = true
	}
	if !scanFound {
		return fmt.Errorf("ZAP plan must contain a request-producing scan job")
	}
	if !reportFound {
		return fmt.Errorf("ZAP plan must contain the required report job")
	}
	return nil
}

func validateZAPEnvironment(root *yaml.Node, configuredBaseURL string) error {
	if err := requireYAMLKeys(root, "env", "jobs"); err != nil {
		return fmt.Errorf("ZAP plan: %w", err)
	}
	env := yamlMappingValue(root, "env")
	if env == nil || env.Kind != yaml.MappingNode {
		return fmt.Errorf("ZAP plan env must be a mapping")
	}
	if err := requireYAMLKeys(env, "contexts"); err != nil {
		return fmt.Errorf("ZAP env: %w", err)
	}
	contexts := yamlMappingValue(env, "contexts")
	if contexts == nil || contexts.Kind != yaml.SequenceNode || len(contexts.Content) == 0 {
		return fmt.Errorf("ZAP plan requires at least one context")
	}
	base, err := url.ParseRequestURI(configuredBaseURL)
	if err != nil || base.RawQuery != "" || base.Fragment != "" {
		return fmt.Errorf("ZAP base URL must not contain query or fragment")
	}
	baseFound := false
	for _, context := range contexts.Content {
		if err := requireYAMLKeys(context, "name", "urls"); err != nil {
			return fmt.Errorf("ZAP context: %w", err)
		}
		if scalarValue(yamlMappingValue(context, "name")) == "" {
			return fmt.Errorf("ZAP context name is required")
		}
		urls := yamlMappingValue(context, "urls")
		if urls == nil || urls.Kind != yaml.SequenceNode || len(urls.Content) == 0 {
			return fmt.Errorf("ZAP context urls are required")
		}
		for _, item := range urls.Content {
			candidate, parseErr := url.ParseRequestURI(item.Value)
			if parseErr != nil || candidate.RawQuery != "" || candidate.Fragment != "" {
				return fmt.Errorf("ZAP context URL is invalid")
			}
			if scopeAllowsTarget(item.Value, []string{configuredBaseURL}) && scopeAllowsTarget(configuredBaseURL, []string{item.Value}) {
				baseFound = true
			}
		}
	}
	if !baseFound {
		return fmt.Errorf("ZAP context must contain the configured base URL")
	}
	return nil
}

func finalizeStatus(res *Result, tool Tool, target Target, native NativeResult, normalizationErr error) {
	mapped, known := tool.ExitCodes[native.ExitCode]
	if known && mapped == StatusTimeout {
		res.Status = StatusTimeout
		return
	}
	inconsistent := known && mapped == StatusFindings && len(res.Findings) == 0
	if inconsistent {
		res.Errors = append(res.Errors, "exit code indicated findings but normalization produced none")
	}
	if known && isCleanExit(mapped) && len(res.Coverage.Examined) == 0 && len(res.Coverage.Skipped) == 0 && len(res.Coverage.Uncovered) == 0 {
		res.Coverage.Uncovered = []string{target.Locator}
	}
	hasFindings := len(res.Findings) > 0
	if !known {
		res.Errors = append(res.Errors, fmt.Sprintf("unmapped exit code %d", native.ExitCode))
		res.Status = statusForFailedRun(hasFindings)
		return
	}
	if mapped == StatusError || native.Err != nil || normalizationErr != nil || inconsistent {
		res.Status = statusForFailedRun(hasFindings)
		return
	}
	if len(res.Coverage.Skipped) > 0 || len(res.Coverage.Uncovered) > 0 || len(res.Errors) > 0 {
		res.Status = StatusPartial
		return
	}
	if hasFindings {
		res.Status = StatusFindings
		return
	}
	if isCleanExit(mapped) && len(res.Coverage.Examined) > 0 {
		// A clean run is a bounded negative result, never a statement that
		// the target is safe: it says only that this harness, over this
		// coverage, found nothing.
		res.Status = StatusNotFoundUnder
		if res.Bounded == nil {
			res.Bounded = &BoundedScope{}
		}
		if res.Bounded.Coverage == "" {
			res.Bounded.Coverage = summarizeCoverage(res.Coverage.Examined)
		}
		if res.Bounded.Environment == "" {
			res.Bounded.Environment = tool.Name + " " + tool.Version
		}
		if res.Bounded.Bounds == "" && res.Replay.Seed != nil {
			res.Bounded.Bounds = fmt.Sprintf("seed=%d", *res.Replay.Seed)
		}
		return
	}
	res.Status = StatusError
	res.Errors = append(res.Errors, "execution did not satisfy the bounded-negative criteria")
}

func stableEnvironment(in map[string]string) map[string]string {
	out := map[string]string{}
	for _, k := range []string{"os", "arch", "kernel", "runtime", "compiler", "build", "assembly_digest"} {
		if v := in[k]; v != "" {
			out[k] = v
		}
	}
	return out
}

func (r *Runner) Run(ctx context.Context, cfg RunConfig) Result {
	cfg = cloneRunConfig(cfg)
	res := Result{Stages: append([]string(nil), workflowStages...)}
	inv, tool, err := r.registry.BuildInvocation(cfg)
	if err != nil {
		var applicability *ApplicabilityError
		if errors.As(err, &applicability) {
			res.Status = StatusNotApplicable
		} else {
			res.Status = StatusError
		}
		res.Errors = []string{NewRedactor(cfg.Sensitive...).Text(err.Error())}
		return res
	}
	cfgJSON, err := canonicalJSON(cfg)
	if err != nil {
		res.Status = StatusError
		res.Errors = []string{err.Error()}
		return res
	}
	publicCfg := redactedRunConfig(cfg)
	publicJSON, _ := canonicalJSON(publicCfg)
	res.Replay = Replay{Target: publicCfg.Target, Tool: tool.Name, ToolVersion: tool.Version, ImageDigest: tool.ImageDigest, ToolArtifactDigest: tool.ToolArtifactDigest, WrapperDigest: tool.WrapperDigest, PlatformDigest: tool.PlatformDigests[runtime.GOARCH], Knowledge: cloneStringMap(tool.KnowledgeDigests), Configuration: publicJSON, ConfigurationID: sha256Digest(cfgJSON), Seed: cloneInt64(cfg.Seed), InputDigests: []string{cfg.Target.Digest}}
	if r.sandbox == nil {
		res.Status = StatusError
		res.Errors = []string{"no sandbox executor configured"}
		return res
	}
	native := r.sandbox.Execute(ctx, ExecutionRequest{Invocation: inv, Tool: cloneTool(tool), Config: cloneRunConfig(cfg)})
	res.Coverage = Coverage{Examined: sortedUnique(native.Examined), Skipped: sortedUnique(native.Skipped), Uncovered: sortedUnique(native.Uncovered)}
	if native.Bounded != nil {
		bounded := *native.Bounded
		res.Bounded = &bounded
	}
	res.Replay.Environment = stableEnvironment(native.Environment)
	res.Replay.SandboxDigest = native.Environment["sandbox_digest"]
	redactor := NewRedactor(cfg.Sensitive...)
	if int64(len(native.Output)) > tool.Budgets.MaxOutputSize {
		native.Err = fmt.Errorf("native output exceeds %d-byte budget", tool.Budgets.MaxOutputSize)
	}
	if len(native.Output) > 0 {
		res.Artifacts = []Artifact{{Name: "raw-output", MediaType: tool.OutputMediaType, Digest: sha256Digest(native.Output), Size: len(native.Output), Data: append([]byte(nil), native.Output...)}}
	}
	for _, artifact := range native.Artifacts {
		artifact.Data = append([]byte(nil), artifact.Data...)
		res.Artifacts = append(res.Artifacts, artifact)
	}
	if native.TimedOut || errors.Is(native.Err, context.DeadlineExceeded) {
		res.Status = StatusTimeout
		if native.Err != nil {
			res.Errors = []string{redactor.Text(native.Err.Error())}
		}
		return res
	}
	err = r.normalizeNative(tool, cfg.Target, native.Output, redactor, &res)
	stableRecords(res.Findings)
	if native.Err != nil {
		res.Errors = append(res.Errors, redactor.Text(native.Err.Error()))
	}
	finalizeStatus(&res, tool, cfg.Target, native, err)
	return res
}

