func NewRegistry(workDir string, opts ...RegistryOption) *Registry {
	r := &Registry{
		tools:           make(map[string]agentsdk.Tool),
		workDir:         workDir,
		permissionMode:  policy.PermissionModeWorkspaceWrite,
		gitRemoteWrites: policy.GitRemoteWritesEnabled,
	}
	for _, opt := range opts {
		opt(r)
	}
	config := sandbox.ConfigFromEnv()
	if r.commandSandboxConfig != nil {
		config = *r.commandSandboxConfig
	}
	config.WorkspaceRoot = workDir
	r.commandSandboxConfig = &config
	if r.lspTool == nil {
		r.lspTool = &lsp.Tool{}
	}
	r.lspTool.Config.Executor = r.bashExecutor()
	r.lspTool.Config.AllowUnsafeUnconfined = false

	var allTools []agentsdk.Tool
	if r.permissionMode == policy.PermissionModeWorkspaceWrite {
		allTools = []agentsdk.Tool{
			&search.ListFilesTool{},
			&search.ReadFileTool{},
			&search.GlobTool{},
			&search.GrepTool{},
			r.lspTool,
			&shell.WorkspaceWriteBashTool{BashTool: shell.BashTool{
				Executor:        r.bashExecutor(),
				GitRemoteWrites: r.gitRemoteWrites,
			}},
			&fs.WorkspaceWriteFileTool{},
			&fs.WorkspaceEditTool{},
			&fs.ApplyPatchTool{},
			&fs.MoveTool{},
			&fs.DeleteTool{},
		}
	} else {
		allTools = []agentsdk.Tool{
			&search.ListFilesTool{},
			&search.ReadFileTool{},
			&search.GlobTool{},
			&search.GrepTool{},
			r.lspTool,
		}
		if !r.permissionMode.AllowsWriteTools() {
			allTools = append(allTools, &shell.ReadOnlyBashTool{BashTool: shell.BashTool{
				Executor:        r.bashExecutor(),
				GitRemoteWrites: r.gitRemoteWrites,
			}})
		} else {
			allTools = append(allTools,
				&shell.BashTool{Executor: r.bashExecutor(), GitRemoteWrites: r.gitRemoteWrites},
				&fs.FileWriteTool{},
				&fs.FileEditTool{},
				&fs.ApplyPatchTool{},
				&fs.MoveTool{},
				&fs.DeleteTool{},
			)
		}
	}
	if !r.disableWeb {
		allTools = append(allTools, &web.FetchTool{AllowPrivateNetworkURLs: r.allowPrivateNetworkURLs})
	}
	if r.signals {
		allTools = append(allTools, &signal.AskUserQuestionTool{}, &signal.PresentPlanTool{})
	}
	for _, tool := range allTools {
		r.Register(tool)
	}
	if r.asyncShell && r.permissionMode.AllowsWriteTools() {
		manager := shell.NewAsyncManager(r.bashExecutor())
		r.asyncShellManager = manager
		r.Register(&shell.BashStartTool{Manager: manager, Mode: r.permissionMode, GitRemoteWrites: r.gitRemoteWrites})
		r.Register(&shell.BashPollTool{Manager: manager})
		r.Register(&shell.BashKillTool{Manager: manager})
	}
	if r.interactiveTerminal &&
		r.permissionMode == policy.PermissionModeDangerFullAccess &&
		r.gitRemoteWrites == policy.GitRemoteWritesEnabled {
		manager := shell.NewTerminalManager(r.bashExecutor())
		r.terminalManager = manager
		r.Register(&shell.TerminalTool{Manager: manager, Mode: r.permissionMode, GitRemoteWrites: r.gitRemoteWrites})
	}
	if r.thinkTool {
		r.Register(&signal.ThinkTool{})
	}
	// Chromium cannot bind public-only URL validation to redirects, DNS, and
	// subresources. Register Browser only behind the explicit unrestricted
	// networking opt-in; WebFetch remains the destination-confined default.
	effectiveBrowserScreenshotDir := ""
	if r.browser && r.allowPrivateNetworkURLs {
		effectiveBrowserScreenshotDir = r.browserScreenshotDir
		if effectiveBrowserScreenshotDir == "" {
			effectiveBrowserScreenshotDir = browser.DefaultScreenshotDir()
		}
		r.Register(&browser.Tool{
			AllowPrivateNetworkURLs: true,
			Executor:                r.bashExecutor(),
			ScreenshotDir:           effectiveBrowserScreenshotDir,
		})
	}
	if r.visionTool != nil {
		r.visionTool.AllowPrivateNetworkURLs = r.allowPrivateNetworkURLs
		if effectiveBrowserScreenshotDir != "" {
			r.visionTool.AllowedImageDirs = append(r.visionTool.AllowedImageDirs, effectiveBrowserScreenshotDir)
		}
		r.Register(r.visionTool)
	}
	if r.memoryTool != nil {
		r.Register(r.memoryTool)
	}
	if r.attachRepositoryTool != nil {
		r.Register(r.attachRepositoryTool)
	}
	if r.pullRequestTool != nil {
		r.Register(r.pullRequestTool)
	}
	if r.issueTool != nil {
		r.Register(r.issueTool)
	}
	return r
}

