func (m *AsyncManager) start(ctx context.Context, in asyncStartInput, workDir string, mode policy.PermissionMode) (string, error) {
	if m == nil {
		return "", errors.New("async shell manager is nil")
	}
	executor := m.executor
	if executor == nil {
		executor = sandbox.Default()
	}
	timeout := effectiveMaxBashTimeout()
	if in.Timeout > 0 {
		timeout = time.Duration(in.Timeout) * time.Millisecond
		if timeout > effectiveMaxBashTimeout() {
			timeout = effectiveMaxBashTimeout()
		}
	}
	mode = policy.NormalizePermissionMode(string(mode))
	req := sandbox.Request{
		Argv:           []string{"bash", "--noprofile", "--norc", "-c", in.Command},
		WorkDir:        workDir,
		PermissionMode: mode,
		// Match synchronous Bash: workspace-write development commands need
		// egress, while read-only commands stay network-isolated.
		AllowNetwork: mode == policy.PermissionModeWorkspaceWrite,
	}
	built, err := executor.Build(ctx, req)
	if err != nil {
		return "", err
	}

	args := append([]string(nil), built.Args[1:]...)
	env := append([]string(nil), built.Env...)
	cmd := exec.Command(built.Path, args...)
	cmd.Dir = built.Dir
	cmd.Env = env
	configurePlatformProcAttrs(cmd)

	output := newBoundedWriter(effectiveMaxBashOutputBytes())
	attachBoundedPipes(cmd, output)

	runCtx := context.Background()
	cancel := func() {}
	if timeout > 0 {
		runCtx, cancel = context.WithTimeout(runCtx, timeout)
	}

	m.mu.Lock()
	m.sweepFinishedLocked()
	m.nextID++
	id := "bash-" + strconv.Itoa(m.nextID)
	job := &asyncJob{
		id:          id,
		command:     in.Command,
		description: strings.TrimSpace(in.Description),
		startedAt:   time.Now(),
		timeout:     timeout,
		cmd:         cmd,
		cancel:      cancel,
		output:      output,
		done:        make(chan struct{}),
		exitCode:    -1,
	}
	m.jobs[id] = job
	m.mu.Unlock()

	if err := cmd.Start(); err != nil {
		cancel()
		m.mu.Lock()
		delete(m.jobs, id)
		m.mu.Unlock()
		return "", err
	}

	go job.wait(runCtx)
	return id, nil
}

