func openAIOAuthEnvs(run *platformv1alpha1.AgentRun) []corev1.EnvVar {
	if !requiresProviderOAuth(run) {
		return nil
	}
	if requiresAnthropicOAuth(run) {
		return []corev1.EnvVar{{Name: anthropicOAuthAuthJSONEnv, Value: openAIOAuthAuthJSONPath}}
	}
	if requiresCopilotOAuth(run) {
		return []corev1.EnvVar{{Name: copilotOAuthAuthJSONEnv, Value: openAIOAuthAuthJSONPath}}
	}
	return []corev1.EnvVar{
		{Name: "OPENAI_OAUTH_AUTH_JSON_PATH", Value: openAIOAuthAuthJSONPath},
		{Name: "OPENAI_OAUTH_ACCOUNT_ID_PATH", Value: openAIOAuthAccountIDPath},
	}
}

func providerOAuthEnvs(run *platformv1alpha1.AgentRun) []corev1.EnvVar {
	var envs []corev1.EnvVar
	for _, ref := range providerOAuthSecretEntries(run) {
		authJSONPath := providerOAuthMountPath(ref.Provider) + "/auth.json"
		switch ref.Provider {
		case "anthropic":
			envs = append(envs, corev1.EnvVar{Name: anthropicOAuthAuthJSONEnv, Value: authJSONPath})
		case "copilot":
			envs = append(envs, corev1.EnvVar{Name: copilotOAuthAuthJSONEnv, Value: authJSONPath})
		default: // openai
			envs = append(envs,
				corev1.EnvVar{Name: "OPENAI_OAUTH_AUTH_JSON_PATH", Value: authJSONPath},
				corev1.EnvVar{Name: "OPENAI_OAUTH_ACCOUNT_ID_PATH", Value: providerOAuthMountPath(ref.Provider) + "/account-id"},
			)
		}
	}
	return envs
}

func providerOAuthFallbackEnvs(run *platformv1alpha1.AgentRun) []corev1.EnvVar {
	authPaths := map[string][]string{}
	var openAIAccountIDPaths []string
	for _, entry := range providerOAuthFallbackEntries(run) {
		mountPath := providerOAuthFallbackMountPath(entry)
		authPaths[entry.Provider] = append(authPaths[entry.Provider], mountPath+"/auth.json")
		if entry.Provider == "openai" {
			openAIAccountIDPaths = append(openAIAccountIDPaths, mountPath+"/account-id")
		}
	}
	var envs []corev1.EnvVar
	if paths := authPaths["openai"]; len(paths) > 0 {
		envs = append(envs,
			corev1.EnvVar{Name: "OPENAI_OAUTH_FALLBACK_AUTH_JSON_PATHS", Value: strings.Join(paths, ",")},
			corev1.EnvVar{Name: "OPENAI_OAUTH_FALLBACK_ACCOUNT_ID_PATHS", Value: strings.Join(openAIAccountIDPaths, ",")},
		)
	}
	if paths := authPaths["anthropic"]; len(paths) > 0 {
		envs = append(envs, corev1.EnvVar{Name: "ANTHROPIC_OAUTH_FALLBACK_AUTH_JSON_PATHS", Value: strings.Join(paths, ",")})
	}
	if paths := authPaths["copilot"]; len(paths) > 0 {
		envs = append(envs, corev1.EnvVar{Name: "COPILOT_OAUTH_FALLBACK_AUTH_JSON_PATHS", Value: strings.Join(paths, ",")})
	}
	return envs
}

